"use strict";

const root = document.querySelector("#app");
const state = { token: localStorage.getItem("milton_token") || "", data: null, page: "dashboard", query: "", selectedClient: null, drawerData: null, selectedSlot: null, slotDate: today(), slots: [], scheduleCloserId:"", scheduleView:"day", clientStatusFilter:"", trialFilter:"upcoming", kanbanFilter:"all", analyticsFilters:null, analyticsReport:null, analyticsSort:{managers:"revenue",closers:"revenue",sources:"revenue"}, analyticsUi:{collapsed:false,drawerOpen:false,manualExpanded:false}, analyticsScrollHandler:null };
const paymentIdempotencyKeys = new Map();
let realtimeSource=null,realtimeTimer=null,realtimeEpoch=0,realtimePending=new Set();

function today() { const d = new Date(), off = d.getTimezoneOffset(); return new Date(d.getTime() - off * 60000).toISOString().slice(0, 10); }
function shiftDate(value,days){const d=new Date(`${value}T12:00:00`);d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)}
function analyticsPeriod(preset){const current=today(),d=new Date(`${current}T12:00:00`),weekday=(d.getDay()+6)%7,monthStart=`${current.slice(0,8)}01`;if(preset==='today')return{from:current,to:current};if(preset==='yesterday'){const y=shiftDate(current,-1);return{from:y,to:y}}if(preset==='week')return{from:shiftDate(current,-weekday),to:current};if(preset==='previousWeek'){const to=shiftDate(current,-weekday-1);return{from:shiftDate(to,-6),to}}if(preset==='previousMonth'){const first=new Date(`${monthStart}T12:00:00`);first.setMonth(first.getMonth()-1);const from=first.toISOString().slice(0,10),to=shiftDate(monthStart,-1);return{from,to}}return{from:monthStart,to:current}}
function defaultAnalyticsFilters(){const me=state.data?.me;return{preset:'month',...analyticsPeriod('month'),dateType:'trial',managerId:me?.role==='MANAGER'?me.id:'',closerId:me?.role==='CLOSER'?me.id:'',sourceId:'',statusId:'',paymentMethodId:'',refusalReasonId:'',tagId:'',compare:false,includeArchived:false}}
function money(n) { return new Intl.NumberFormat("ru-KZ").format(Number(n || 0)) + " ₸"; }
function dateTime(v) { return v ? new Intl.DateTimeFormat("ru-RU", { timeZone: "Asia/Almaty", day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" }).format(new Date(v)) : "—"; }
function time(v) { return new Intl.DateTimeFormat("ru-RU", { timeZone: "Asia/Almaty", hour: "2-digit", minute: "2-digit" }).format(new Date(v)); }
function escapeHtml(v = "") { return String(v).replace(/[&<>'"]/g, (x) => ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", "'":"&#39;", '"':"&quot;" }[x])); }
function initials(name = "?") { return name.split(/\s+/).map((x) => x[0]).join("").slice(0, 2).toUpperCase(); }
function avatar(u, role) { return `<span class="avatar" title="${role}: ${escapeHtml(u?.name || "Не назначен")}" aria-label="${role}: ${escapeHtml(u?.name || "Не назначен")}">${u?.avatarUrl?`<img src="${escapeHtml(u.avatarUrl)}" alt="${escapeHtml(u.name||role)}">`:initials(u?.name)}<i class="role-dot">${role === "Менеджер" ? "M" : role === "Клоузер" ? "C" : "A"}</i></span>`; }
function avatars(c) { return `<span class="avatars">${avatar(c.manager,"Менеджер")}${avatar(c.closer,"Клоузер")}</span>`; }
const defaultNames = { st_scheduled:"Запланирован", st_completed:"Завершён", st_reschedule:"Перенесён", st_no_show:"Неявка", st_refusal:"Отказ", st_payment:"Оплата", src_1:"Instagram", src_2:"TikTok", src_3:"Рекомендация", src_4:"Школа", tag_1:"Горячий", tag_2:"VIP", tag_3:"Повторный", tag_4:"Школа", reason_1:"Цена", reason_2:"Расписание", reason_3:"Пока не готов", reason_4:"Выбрал другую школу", method_1:"Kaspi Gold", method_2:"Рассрочка Kaspi", method_3:"Наличные", method_4:"Перевод" };
function displayName(item) { return item ? (defaultNames[item.id] || item.name) : "—"; }
function statusPill(s) { return `<span class="status-pill" style="--status:${s?.color || "#7c879e"}">${escapeHtml(s ? displayName(s) : "Неизвестно")}</span>`; }
function tagPills(tags = []) { return `<span class="tags">${tags.map((t) => `<span class="tag" style="background:${t.color || "#edf0f5"}">${escapeHtml(displayName(t))}</span>`).join("")}</span>`; }
function roleLabel(role) { return ({ ADMIN:"Администратор", MANAGER:"Менеджер", CLOSER:"Клоузер" })[role] || role; }
function profileStatusLabel(value) { return ({ WORKING:"Работает", DAY_OFF:"Выходной", NOT_ACCEPTING:"Не принимает пробные уроки" })[value] || value; }
function actionTypeLabel(value) { return ({ MARK_NO_SHOW:"неявка", REQUIRE_REFUSAL_REASON:"требуется причина отказа", REQUIRE_RESCHEDULE:"требуется перенос", REQUIRE_PAYMENT:"требуются данные оплаты" })[value] || value; }
function can(key) { return state.data?.access?.permissions?.[key] === true; }
function canAny(...keys) { return keys.some(can); }

async function request(url, options = {}) {
  let payload, paymentFingerprint = null; const headers={ "Content-Type":"application/json", ...(state.token ? { Authorization:`Bearer ${state.token}` } : {}), ...(options.headers || {}) };
  if(options.body&&typeof options.body==="string"){try{payload=JSON.parse(options.body)}catch{};if(payload&&/^\/api\/clients\/[^/]+\/(status|archive|restore)$/.test(url)&&state.drawerData?.client?.version!==undefined)payload.version??=state.drawerData.client.version;if(payload&&/^\/api\/payments\/[^/]+\/correct$/.test(url)){const payment=state.drawerData?.payments?.find(item=>url.includes(`/api/payments/${item.id}/`));if(payment?.version!==undefined)payload.version??=payment.version}const selectedStatus=state.data?.statuses?.find(item=>item.id===payload?.statusId);if(selectedStatus?.actionType==="REQUIRE_PAYMENT"){paymentFingerprint=`${url}:${JSON.stringify(payload)}`;const key=paymentIdempotencyKeys.get(paymentFingerprint)||crypto.randomUUID();paymentIdempotencyKeys.set(paymentFingerprint,key);headers["Idempotency-Key"]=key}options={...options,body:JSON.stringify(payload)}}
  const response = await fetch(url, { ...options, headers });
  const type = response.headers.get("content-type") || ""; const value = type.includes("json") ? await response.json() : await response.text();
  if (!response.ok) { const error = new Error(value.error || "Что-то пошло не так"); error.status = response.status; error.data = value; throw error; }
  if(paymentFingerprint)paymentIdempotencyKeys.delete(paymentFingerprint);
  return value;
}
function toast(message, error = false) { const el = document.createElement("div"); el.className = `toast ${error ? "error" : ""}`; el.textContent = message; document.querySelector("#toast-root").append(el); setTimeout(() => el.remove(), 2800); }

async function boot() {
  if (!state.token) return renderLogin();
  try { state.data = await request("/api/bootstrap"); document.documentElement.style.setProperty("--accent", state.data.branding.accentColor); renderShell(); startRealtime(); } catch (e) { localStorage.removeItem("milton_token"); state.token = ""; stopRealtime(); renderLogin(); }
}
function stopRealtime(){realtimeEpoch++;realtimePending.clear();if(realtimeSource){realtimeSource.close();realtimeSource=null}clearTimeout(realtimeTimer);realtimeTimer=null}
function scheduleRealtimeRefresh(event){let resources=['bootstrap'];if(event?.type==='invalidate'){try{const parsed=JSON.parse(event.data||'{}');resources=Array.isArray(parsed.resources)?parsed.resources:['bootstrap']}catch{resources=['bootstrap']}}resources.forEach((item)=>realtimePending.add(item));clearTimeout(realtimeTimer);const epoch=realtimeEpoch;realtimeTimer=setTimeout(async()=>{if(!state.token||epoch!==realtimeEpoch)return;const requested=[...realtimePending];realtimePending.clear();const selected=state.selectedClient,authToken=state.token,full=requested.includes('bootstrap');try{const nextData=await request(full?'/api/bootstrap':`/api/sync?resources=${encodeURIComponent(requested.join(','))}`);if(state.token!==authToken||epoch!==realtimeEpoch)return;state.data=full?nextData:{...state.data,...nextData};document.documentElement.style.setProperty('--accent',state.data.branding.accentColor);renderShell();if(selected&&(full||requested.some((item)=>['clients','trials','payments'].includes(item)))){state.drawerData=await request(`/api/clients/${selected}`);if(state.token===authToken&&epoch===realtimeEpoch)renderDrawer()}}catch(err){if(err.status===401&&epoch===realtimeEpoch){stopRealtime();localStorage.removeItem('milton_token');state.token='';renderLogin()}}},160)}
function startRealtime(){stopRealtime();if(!state.token||typeof EventSource==='undefined')return;realtimeSource=new EventSource('/api/events');realtimeSource.addEventListener('ready',scheduleRealtimeRefresh);realtimeSource.addEventListener('invalidate',scheduleRealtimeRefresh)}
function renderLogin() {
  root.innerHTML = `<main class="login-page"><section class="login-hero"><div class="brand"><span class="brand-mark">M</span> Milton CRM</div><div class="hero-copy"><h1>Каждый лид.<br>Одна общая история.</h1><p>От первого звонка до пробного урока и оплаты — вся команда работает с единой историей клиента.</p><div class="flow"><span>Лид</span><i>→</i><span>Пробный урок</span><i>→</i><span>Оплата</span></div></div><small>Языковой центр Milton · Asia/Almaty</small></section><section class="login-main"><form class="login-card" id="login-form"><div class="eyebrow">С возвращением</div><h2>Вход в Milton</h2><p>Войдите под своей рабочей учётной записью.</p><div class="field"><label>Email или логин</label><input name="login" type="email" value="admin@milton.kz" required></div><div class="field"><label>Пароль</label><input name="password" type="password" value="demo123" required></div><button class="btn btn-primary btn-wide">Войти</button><div class="demo-logins"><b>Демо-аккаунты</b><br>Администратор: admin@milton.kz<br>Менеджер: manager@milton.kz<br>Клоузер: closer@milton.kz<br>Пароль: demo123</div></form></section></main>`;
  document.querySelector("#login-form").addEventListener("submit", async (e) => { e.preventDefault(); const button = e.currentTarget.querySelector("button"); button.disabled = true; button.textContent = "Входим…"; try { const value = await request("/api/login", { method:"POST", body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget))) }); state.token = value.token;state.analyticsFilters=null; localStorage.setItem("milton_token", value.token); await boot(); } catch (err) { toast(err.message, true); button.disabled = false; button.textContent = "Войти"; } });
}

const menus = {
  ADMIN: [["dashboard","▦","Главная","dashboard.view"],["kanban","▥","CRM","crm.view"],["schedule","◫","Расписание","schedule.view"],["clients","◉","Клиенты","clients.view"],["clientArchive","▤","Архив клиентов","clients.archive"],["users","♙","Сотрудники","users.view"],["roles","⌘","Роли и права","users.manageRoles"],["analytics","◒","Аналитика","analytics.view"],["settings","⚙","Настройки","settings"],["audit","≡","Аудит","audit.view"],["profile","○","Профиль",null]],
  MANAGER: [["register","＋","Регистрация","clients.create"],["trials","◫","Пробные уроки","schedule.view"],["clients","◉","Клиенты","clients.view"],["clientArchive","▤","Архив клиентов","clients.archive"],["analytics","◒","Аналитика","analytics.view"],["profile","○","Профиль",null]],
  CLOSER: [["dashboard","▦","Главная","dashboard.view"],["schedule","◫","Расписание","schedule.view"],["clients","◉","Клиенты","clients.view"],["clientArchive","▤","Архив клиентов","clients.archive"],["kanban","▥","CRM","crm.view"],["analytics","◒","Аналитика","analytics.view"],["profile","○","Профиль",null]]
};
function visibleMenus(me) { return menus[me.role].filter(([, , , permission]) => permission === null || (permission === "settings" ? canAny("settings.manageStatuses","settings.manageRefusalReasons","settings.manageLeadSources","settings.managePaymentMethods","settings.manageTags","settings.manageBranding") : can(permission))); }
function renderShell() {
  const me = state.data.me, availableMenus=visibleMenus(me); if (!availableMenus.some(([key])=>key===state.page)) state.page=availableMenus[0]?.[0]||"profile";
  root.innerHTML = `<div class="shell"><aside class="sidebar"><div class="brand">${state.data.branding.logoUrl?`<img class="brand-logo" src="${escapeHtml(state.data.branding.logoUrl)}" alt="">`:'<span class="brand-mark">M</span>'}<span>${escapeHtml(state.data.branding.companyName)}</span></div><nav class="nav">${availableMenus.map(([key,icon,label]) => `<button data-page="${key}" class="${state.page===key?"active":""}"><span class="nav-icon">${icon}</span>${label}</button>`).join("")}</nav><div class="profile-mini">${avatar(me,roleLabel(me.role))}<div class="meta"><strong>${escapeHtml(me.name)}</strong><small>${roleLabel(me.role)}</small></div></div></aside><section class="main"><header class="topbar"><span class="page-title">${pageTitle()}</span><div class="searchbox"><input id="global-search" value="${escapeHtml(state.query)}" placeholder="Поиск по клиентам, телефону, сотрудникам…"></div><button class="icon-btn" title="Уведомления">♧${state.data.notifications.some((n)=>!n.readAt)?'<i class="badge-dot"></i>':''}</button><button id="logout" class="icon-btn" title="Выйти">↗</button></header><main class="content" id="content"></main></section></div>`;
  document.querySelectorAll("[data-page]").forEach((b) => b.onclick = () => { state.page = b.dataset.page; state.selectedClient = null; renderShell(); });
  document.querySelector('.icon-btn[title="Уведомления"]').onclick=showNotifications;
  root.onclick=handleToolbarClick;
  document.querySelector("#logout").onclick = () => { stopRealtime();localStorage.removeItem("milton_token"); state.token = ""; state.data = null;state.analyticsFilters=null; renderLogin(); };
  document.querySelector("#global-search").addEventListener("input", (e) => { state.query = e.target.value; state.page = "clients"; renderPage(); });
  renderPage();
}
function handleToolbarClick(event){const button=event.target.closest('.toolbar button.chip');if(!button)return;const label=button.textContent.trim();if(state.page==='clients'){state.clientStatusFilter=label.startsWith('Все:')?'':(state.data.statuses.find(s=>displayName(s)===label)?.id||'');renderPage()}else if(state.page==='trials'){state.trialFilter=label==='Сегодня'?'today':label==='Без результата'?'overdue':'upcoming';renderPage()}else if(state.page==='kanban'){state.kanbanFilter=label==='Сегодня'?'today':label==='Мои клиенты'?'mine':'all';renderPage()}else if(state.page==='schedule'){state.scheduleView=label==='Неделя'?'week':'day';renderPage()}}
function postRenderEnhancements(){
  const outlet=document.querySelector('#content');if(!outlet)return;
  if(state.page==='clients')outlet.querySelectorAll('.toolbar button').forEach(btn=>btn.classList.toggle('active',btn.textContent.startsWith('Все:')?!state.clientStatusFilter:state.data.statuses.find(s=>s.id===state.clientStatusFilter)&&btn.textContent.trim()===displayName(state.data.statuses.find(s=>s.id===state.clientStatusFilter))));
  if(state.page==='users'){
    const add=outlet.querySelector('[data-add-user]');if(add){const clone=add.cloneNode(true);add.replaceWith(clone);clone.onclick=()=>showUserModalV2();}
    outlet.querySelectorAll('[data-edit-user]').forEach(button=>{const clone=button.cloneNode(true),account=state.data.users.find(u=>u.id===button.dataset.editUser);button.replaceWith(clone);clone.onclick=()=>showUserModalV2(account)});
    const rows=outlet.querySelectorAll('tbody tr');state.data.users.forEach((u,index)=>{const cell=rows[index]?.lastElementChild;if(!cell)return;if(!u.active&&can('users.archive')){const restore=document.createElement('button');restore.className='btn btn-secondary';restore.textContent='Восстановить';restore.onclick=async()=>{try{await request(`/api/admin/users/${u.id}/restore`,{method:'POST'});toast('Доступ пользователя восстановлен');await refreshData()}catch(err){toast(err.message,true)}};cell.append(' ',restore)}if(state.data.me.role==='ADMIN'&&!u.isOwner&&u.id!==state.data.me.id){const remove=document.createElement('button');remove.className='btn btn-danger';remove.textContent='Удалить';remove.onclick=()=>showEmployeeDeleteModal(u);cell.append(' ',remove)}});
  }
}
function showNotifications(){const items=state.data.notifications;showModal(`<h2>Уведомления</h2><p>Назначения, переносы, напоминания и результаты пробных уроков.</p><div class="notification-list">${items.length?items.map(n=>`<button class="notification-item ${n.readAt?'':'unread'}" data-notification="${n.id}" data-client-id="${n.clientId||''}"><b>${escapeHtml(({TRIAL_ASSIGNED:'Новый пробный урок',TRIAL_REMINDER:'Скоро пробный урок',TRIAL_RESCHEDULED:'Пробный урок перенесён',CLIENT_REASSIGNED:'Новое назначение',TRIAL_OVERDUE:'Просрочен результат',PAYMENT_RECORDED:'Оплата зарегистрирована'})[n.type]||'Обновление')}</b><span>${escapeHtml(n.content)}</span><small>${dateTime(n.createdAt)}</small></button>`).join(''):emptyState('Уведомлений нет','Новые рабочие события появятся здесь.','')}</div><div class="modal-actions"><button class="btn btn-ghost" data-close-modal>Закрыть</button></div>`);document.querySelectorAll('[data-notification]').forEach(btn=>btn.onclick=async()=>{try{await request(`/api/notifications/${btn.dataset.notification}/read`,{method:'POST'});const cid=btn.dataset.clientId;closeModal();await refreshData();if(cid)openClient(cid)}catch(err){toast(err.message,true)}})}
function pageTitle() { return ({dashboard:"Главная",register:"Регистрация клиента",trials:"Пробные уроки",clients:"Клиенты",clientArchive:"Архив клиентов",kanban:"CRM-доска",schedule:"Расписание",users:"Команда",roles:"Роли и права",analytics:"Аналитика",settings:"Настройки",audit:"Журнал аудита",profile:"Профиль"})[state.page] || "Milton CRM"; }
function renderPage() {
  const outlet = document.querySelector("#content"); if (!outlet) return;
  if(state.page!=="analytics"){document.body.classList.remove("analytics-filter-open");if(state.analyticsScrollHandler){window.removeEventListener("scroll",state.analyticsScrollHandler);state.analyticsScrollHandler=null;}}
  ({ dashboard:renderDashboard, register:renderRegistration, trials:renderTrials, clients:renderClients,clientArchive:renderClientArchive, kanban:renderKanban, schedule:renderSchedule, users:renderUsers, roles:renderRoles, analytics:renderAnalytics, settings:renderSettingsV2, audit:renderAudit, profile:renderProfileV2 }[state.page] || renderDashboard)(outlet);
  setTimeout(postRenderEnhancements,0);
}
function pageHead(kicker, title, copy, action = "") { return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${copy}</p></div>${action}</div>`; }

function renderDashboard(outlet) {
  const d = state.data.dashboard;
  outlet.innerHTML = `${pageHead("Сегодня",`${new Date().getHours()<12?"Доброе утро":"Добрый день"}, ${escapeHtml(state.data.me.name.split(" ")[0])}`,"Главное о вашем рабочем дне.")}<section class="metric-grid"><div class="metric"><span class="metric-label">Пробные уроки сегодня</span><strong>${d.todayTrials}</strong><small>Осталось: ${d.remaining}</small></div><div class="metric" style="--metric:#e6f7f0"><span class="metric-label">Завершено</span><strong>${d.completed}</strong><small>Сегодня</small></div><div class="metric" style="--metric:#e4f4ee"><span class="metric-label">Выручка</span><strong>${money(d.revenue)}</strong><small>Оплат: ${d.payments}</small></div><div class="metric" style="--metric:#fde9e9"><span class="metric-label">Требует внимания</span><strong>${d.overdue}</strong><small class="${d.overdue?'overdue-label':''}">Просроченные результаты</small></div></section><div class="grid-2"><section class="panel"><div class="panel-head"><h2>Пробные уроки сегодня</h2><button class="link" data-go="schedule">Открыть расписание</button></div>${d.upcoming.length ? `<div class="schedule-list">${d.upcoming.map((t)=>scheduleRow(t.client,t)).join("")}</div>` : emptyState("Сегодня нет пробных уроков","На сегодня всё свободно. Новые назначения появятся здесь.", state.data.me.role==="MANAGER"?"Запланировать пробный урок":"")}</section><section class="panel"><div class="panel-head"><h2>Краткий обзор</h2></div><div class="quick-list"><div class="quick-card"><div><b>Все клиенты</b><br><span>Доступные вам</span></div><strong>${d.clients}</strong></div><div class="quick-card"><div><b>Непрочитанные обновления</b><br><span>Назначения и оплаты</span></div><strong>${state.data.notifications.filter((n)=>!n.readAt).length}</strong></div><div class="quick-card"><div><b>Ваш статус</b><br><span>${profileStatusLabel(state.data.me.profileStatus)}</span></div><span class="status-pill" style="--status:#14a06f">Активен</span></div></div></section></div>`;
  bindClientClicks(); const go = outlet.querySelector("[data-go]"); if(go) go.onclick=()=>{state.page=go.dataset.go;renderShell()};
}
function scheduleRow(c,t) { return `<article class="schedule-row ${c.overdue?'overdue':''}" data-client="${c.id}"><div class="time">${time(t.scheduledAt)}</div><div><div class="client-name">${escapeHtml(c.name)}</div><div class="subline">${escapeHtml(c.normalizedPhone)} · ${statusPill(c.status)} ${c.overdue?'<span class="overdue-label">Просрочено</span>':''}</div></div>${avatars(c)}</article>`; }
function emptyState(title,copy,action) { return `<div class="empty"><div class="empty-icon">◌</div><h3>${title}</h3><p>${copy}</p>${action?`<button class="btn btn-primary" data-page-empty="register">${action}</button>`:""}</div>`; }

async function loadSlots(closerId, date) { try { state.slots = await request(`/api/slots?closerId=${encodeURIComponent(closerId)}&date=${date}`); } catch { state.slots = []; } }
function renderRegistration(outlet) {
  const d=state.data, managers=d.users.filter(u=>u.role==="MANAGER"&&u.active), closers=d.users.filter(u=>u.role==="CLOSER"&&u.active); const managerId=d.me.role==="MANAGER"?d.me.id:(managers[0]?.id||""); const closerId=closers.find(c=>c.profileStatus==="WORKING")?.id||closers[0]?.id||"";
  outlet.innerHTML=`${pageHead("Лид → Пробный урок","Запланировать пробный урок","Создайте единую карточку клиента и забронируйте реальное свободное время.")}<div class="registration"><form class="form-card" id="registration-form"><div class="form-grid"><div class="field"><label>Имя клиента *</label><input name="name" placeholder="Имя и фамилия" required></div><div class="field"><label>Номер телефона *</label><input name="phone" placeholder="+7 707 000 00 00" required></div><div class="field"><label>Менеджер</label><select name="managerId" ${d.me.role==='MANAGER'?'disabled':''}>${managers.map(u=>`<option value="${u.id}" ${u.id===managerId?'selected':''}>${escapeHtml(u.name)}</option>`).join('')}</select></div><div class="field"><label>Источник лида</label><select name="leadSourceId"><option value="">Выберите источник</option>${d.leadSources.filter(x=>x.active).sort((a,b)=>a.sortOrder-b.sortOrder).map(x=>`<option value="${x.id}">${escapeHtml(displayName(x))}</option>`).join('')}</select></div><div class="field"><label>Тип пробного урока *</label><select name="trialType" id="trial-type" required><option value="FREE">Бесплатный</option><option value="PAID">Платный</option></select></div><div class="field paid-trial-fields" hidden><label>Сумма пробного урока *</label><input name="trialAmount" type="number" min="0.01" step="0.01" placeholder="Например, 1500"></div><div class="field wide paid-trial-fields" hidden><label>Чек / скриншот оплаты *</label><input name="receipt" type="file" accept="image/png,image/jpeg,image/webp,application/pdf"><small class="subline">JPG, PNG, WEBP или PDF, до 5 МБ</small></div><div class="field wide"><label>Теги клиента</label><div class="toolbar">${d.tags.filter(x=>x.active).map(x=>`<label class="chip"><input type="checkbox" name="tagIds" value="${x.id}"> ${escapeHtml(displayName(x))}</label>`).join('')}</div></div><div class="field wide"><label>Комментарий менеджера</label><textarea name="comment" placeholder="Уровень, цели, удобное расписание и полезный контекст…"></textarea></div><input type="hidden" name="managerIdResolved" value="${managerId}"><input type="hidden" name="slotId" id="slot-id"><div class="wide"><button class="btn btn-primary btn-wide" data-submit-registration>Запланировать пробный урок</button></div></div></form><aside class="availability-card"><div class="panel-head"><h2>Доступность клоузера</h2></div><div class="field"><label>Клоузер *</label><select id="closer-select" name="closerId">${closers.map(u=>`<option value="${u.id}" ${u.id===closerId?'selected':''}>${escapeHtml(u.name)} · ${profileStatusLabel(u.profileStatus).toLowerCase()}</option>`).join('')}</select></div><div class="field"><label>Дата пробного урока *</label><input type="date" id="slot-date" min="${today()}" value="${state.slotDate}"></div><div id="slot-list"><div class="boot" style="min-height:220px"><span class="spinner"></span></div></div></aside></div>`;
  const refresh=async()=>{state.slotDate=document.querySelector('#slot-date').value;state.selectedSlot=null;await loadSlots(document.querySelector('#closer-select').value,state.slotDate);renderSlotList()}; document.querySelector('#closer-select').onchange=refresh;document.querySelector('#slot-date').onchange=refresh;refresh();
  const form=document.querySelector('#registration-form'),typeSelect=form.querySelector('#trial-type');typeSelect.onchange=()=>{const paid=typeSelect.value==='PAID';form.querySelectorAll('.paid-trial-fields').forEach(el=>el.hidden=!paid);form.trialAmount.required=paid;form.receipt.required=paid};typeSelect.onchange();
  form.onsubmit=async(e)=>{e.preventDefault();if(form.dataset.submitting)return;const fd=new FormData(form),closerId=document.querySelector('#closer-select').value;if(!state.selectedSlot)return toast('Выберите свободное время пробного урока',true);const submit=form.querySelector('[data-submit-registration]'),original=submit.textContent;form.dataset.submitting='true';submit.disabled=true;submit.textContent='Сохраняем…';const payload=Object.fromEntries(fd);payload.managerId=payload.managerId||payload.managerIdResolved;payload.closerId=closerId;payload.slotId=state.selectedSlot;payload.tagIds=fd.getAll('tagIds');const receipt=fd.get('receipt');delete payload.receipt;try{if(payload.trialType==='PAID'&&receipt?.size){payload.receiptDataUrl=await receiptFileData(receipt);payload.receiptName=receipt.name}const c=await request('/api/clients',{method:'POST',body:JSON.stringify(payload)});toast('Пробный урок запланирован');await refreshData();openClient(c.id)}catch(err){if(err.status===409&&err.data.clientId)showDuplicate(err.data);else{toast(err.status===409?'Этот слот уже занят':err.message,true);if(err.status===409)await refresh()}}finally{delete form.dataset.submitting;submit.disabled=false;submit.textContent=original}};
}
function receiptFileData(file){return new Promise((resolve,reject)=>{if(!file)return reject(new Error('Прикрепите чек'));if(!['image/png','image/jpeg','image/webp','application/pdf'].includes(file.type))return reject(new Error('Используйте JPG, PNG, WEBP или PDF'));if(file.size>5_000_000)return reject(new Error('Размер чека не должен превышать 5 МБ'));const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Не удалось прочитать чек'));reader.readAsDataURL(file)})}
function renderSlotList(){const box=document.querySelector('#slot-list');if(!box)return;const free=state.slots.filter(s=>s.status==='FREE'),booked=state.slots.length-free.length;box.innerHTML=`<div class="load"><span><b>Занято: ${booked}</b> / свободно: ${free.length}<div class="progress"><i style="width:${state.slots.length?booked/state.slots.length*100:0}%"></i></div></span><span>Всего: ${state.slots.length}</span></div>${state.slots.length?`<div class="slots">${state.slots.map(s=>`<button class="slot ${state.selectedSlot===s.id?'selected':''}" data-slot="${s.id}" ${s.status!=='FREE'?'disabled':''}>${time(s.startAt)}</button>`).join('')}</div>`:emptyState('Расписание отсутствует','Клоузер ещё не опубликовал свободное время на эту дату.','')}`;box.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{state.selectedSlot=b.dataset.slot;document.querySelector('#slot-id').value=state.selectedSlot;renderSlotList()})}
function showDuplicate(info){const archived=Boolean(info.archived);showModal(`<h2>${archived?'Клиент находится в архиве':'Клиент уже существует'}</h2><p>${archived?'Клиент с таким номером находится в архиве. Новый дубликат не создан.':'Клиент с таким номером телефона уже есть. Откройте общую карточку клиента вместо создания дубликата.'}</p><div class="modal-actions"><button class="btn btn-ghost" data-close-modal>Отмена</button>${archived&&!info.canRestore?'':'<button class="btn btn-primary" data-open-existing>Открыть клиента</button>'}</div>`);document.querySelector('[data-open-existing]')?.addEventListener('click',()=>{closeModal();openClient(info.clientId)})}

function filteredClients(){const q=state.query.toLowerCase().trim(),businessToday=today(),source=state.page==='clients'&&q&&can('clients.archive')?[...state.data.clients,...(state.data.archivedClients||[])]:state.data.clients;return source.filter(c=>(!q||[c.name,c.normalizedPhone,c.manager?.name,c.closer?.name,c.status?.name,displayName(c.status)].some(v=>String(v||'').toLowerCase().includes(q)))&&(state.page!=="clients"||!state.clientStatusFilter||c.currentStatusId===state.clientStatusFilter)&&(state.page!=="kanban"||state.kanbanFilter==="all"||(state.kanbanFilter==="today"&&c.activeTrial&&dayFromIso(c.activeTrial.scheduledAt)===businessToday)||(state.kanbanFilter==="mine"&&(c.currentManagerId===state.data.me.id||c.currentCloserId===state.data.me.id))))}
function dayFromIso(value){return new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Almaty"}).format(new Date(value))}
function renderClients(outlet){const clients=filteredClients(),mayCreate=can('clients.create')&&can('schedule.scheduleTrial');outlet.innerHTML=`${pageHead('Общие записи','Клиенты','Одна карточка клиента, единая история назначений и действий.',mayCreate?'<button class="btn btn-primary" data-new>＋ Запланировать урок</button>':'')}<div class="toolbar"><button class="chip active">Все: ${clients.length}</button>${state.data.statuses.filter(s=>s.active).map(s=>`<button class="chip">${escapeHtml(displayName(s))}</button>`).join('')}${can('clients.archive')?'<button class="chip" data-open-archive>Архив</button>':''}</div>${clients.length?`<div class="table-wrap"><table><thead><tr><th>Клиент</th><th>Статус</th><th>Пробный урок</th><th>Команда</th><th>Источник</th><th>Теги</th>${can('payments.view')?'<th>Оплата</th>':''}</tr></thead><tbody>${clients.map(c=>`<tr data-client="${c.id}" class="${c.overdue?'overdue ':''}${c.archivedAt?'archived-row':''}"><td><div class="client-cell"><span class="avatar">${initials(c.name)}</span><div><b>${escapeHtml(c.name)}</b><div class="subline">${escapeHtml(c.normalizedPhone)}</div>${c.archivedAt?'<span class="archive-badge">В архиве</span>':''}</div></div></td><td>${statusPill(c.status)} ${c.overdue?'<div class="overdue-label">Просрочено</div>':''}</td><td>${c.activeTrial?dateTime(c.activeTrial.scheduledAt):'—'}</td><td>${avatars(c)}</td><td>${escapeHtml(displayName(c.leadSource))}</td><td>${tagPills(c.tags)}</td>${can('payments.view')?`<td class="money">${c.paymentTotal?money(c.paymentTotal):'—'}</td>`:''}</tr>`).join('')}</tbody></table></div>`:emptyState('Клиенты не найдены','Измените поиск или запланируйте первый пробный урок.',mayCreate?'Запланировать пробный урок':'')}`;bindClientClicks();outlet.querySelector('[data-new]')?.addEventListener('click',()=>{state.page='register';renderShell()});outlet.querySelector('[data-open-archive]')?.addEventListener('click',()=>{state.page='clientArchive';renderShell()})}
function renderClientArchive(outlet){const q=state.query.toLowerCase().trim(),items=(state.data.archivedClients||[]).filter(c=>!q||[c.name,c.normalizedPhone,c.manager?.name,c.closer?.name,c.archiveReasonLabel].some(v=>String(v||'').toLowerCase().includes(q)));outlet.innerHTML=`${pageHead('Жизненный цикл клиентов','Архив клиентов','Архив скрывает клиента из рабочих списков, сохраняя его историю, уроки и оплаты.')} ${items.length?`<div class="table-wrap"><table><thead><tr><th>Клиент</th><th>Причина</th><th>Архивировал</th><th>Дата</th><th>Менеджер</th><th>Клоузер</th><th></th></tr></thead><tbody>${items.map(c=>`<tr data-client="${c.id}"><td><div class="client-cell"><span class="avatar">${initials(c.name)}</span><div><b>${escapeHtml(c.name)}</b><div class="subline">${escapeHtml(c.normalizedPhone)}</div></div></div></td><td><span class="archive-badge">${escapeHtml(c.archiveReasonLabel||'Архив')}</span></td><td>${escapeHtml(c.archivedBy?.name||'Система')}</td><td>${dateTime(c.archivedAt)}</td><td>${escapeHtml(c.manager?.name||'—')}</td><td>${escapeHtml(c.closer?.name||'—')}</td><td><button class="btn btn-secondary" data-restore-client="${c.id}">Восстановить</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('Архив пуст','Архивированные клиенты появятся здесь.','')}`;bindClientClicks();outlet.querySelectorAll('[data-restore-client]').forEach(btn=>btn.onclick=async event=>{event.stopPropagation();await restoreArchivedClient(btn.dataset.restoreClient)})}
function renderTrials(outlet){const businessToday=today(),trials=state.data.clients.filter(c=>c.activeTrial&&(state.trialFilter==='upcoming'||(state.trialFilter==='today'&&dayFromIso(c.activeTrial.scheduledAt)===businessToday)||(state.trialFilter==='overdue'&&c.overdue))).sort((a,b)=>a.activeTrial.scheduledAt.localeCompare(b.activeTrial.scheduledAt));outlet.innerHTML=`${pageHead('Рабочая область менеджера','Пробные уроки','Следите за запланированными уроками и сразу видьте результаты клоузеров.','<button class="btn btn-primary" data-new>＋ Запланировать урок</button>')}<div class="toolbar"><button class="chip ${state.trialFilter==='upcoming'?'active':''}">Предстоящие</button><button class="chip ${state.trialFilter==='today'?'active':''}">Сегодня</button><button class="chip ${state.trialFilter==='overdue'?'active':''}">Без результата</button></div><section class="panel">${trials.length?`<div class="schedule-list">${trials.map(c=>scheduleRow(c,c.activeTrial)).join('')}</div>`:emptyState('Пробные уроки не найдены','Для выбранного фильтра нет пробных уроков.','Запланировать пробный урок')}</section>`;bindClientClicks();outlet.querySelector('[data-new]')?.addEventListener('click',()=>{state.page='register';renderShell()})}
function renderKanban(outlet){
  const statuses=state.data.statuses.filter(s=>s.active).sort((a,b)=>a.sortOrder-b.sortOrder),clients=filteredClients(),canChange=canAny('clients.changeStatus','crm.changeStatus');
  outlet.innerHTML=`${pageHead('Активная воронка','CRM-доска','Колонки и цвета соответствуют активным статусам, настроенным администратором.')}<div class="toolbar"><button class="chip ${state.kanbanFilter==='all'?'active':''}">Все клиенты</button><button class="chip ${state.kanbanFilter==='today'?'active':''}">Сегодня</button><button class="chip ${state.kanbanFilter==='mine'?'active':''}">Мои клиенты</button></div><div class="kanban">${statuses.map(s=>{const items=clients.filter(c=>c.currentStatusId===s.id);return `<section class="kanban-col"><header class="kanban-title"><span><i style="--col:${s.color}"></i>${escapeHtml(displayName(s))}</span><span class="count">${items.length}</span></header>${items.map(c=>`<article class="kanban-card ${c.overdue?'overdue':''}" style="--col:${s.color}" data-client="${c.id}"><h3>${escapeHtml(c.name)}</h3><span class="phone">${escapeHtml(c.normalizedPhone)}</span>${c.activeTrial?`<div class="subline">◷ ${dateTime(c.activeTrial.scheduledAt)}</div>`:''}${c.overdue?'<div class="overdue-label">! Результат просрочен</div>':''}<footer class="kanban-card-foot">${tagPills(c.tags)}${avatars(c)}</footer>${canChange?'<button class="link quick-status">Изменить статус</button>':''}</article>`).join('')}</section>`}).join('')}</div>`;
  bindClientClicks();outlet.querySelectorAll('.quick-status').forEach(btn=>btn.onclick=async event=>{event.stopPropagation();const cid=btn.closest('[data-client]').dataset.client;await openClient(cid);showStatusModalV2()});
}

async function loadScheduleSlots(closerId,date,view){if(view==='day'){await loadSlots(closerId,date);return state.slots}const dates=Array.from({length:7},(_,i)=>shiftDate(date,i)),groups=await Promise.all(dates.map(day=>request(`/api/slots?closerId=${encodeURIComponent(closerId)}&date=${day}`)));state.slots=groups.flat();return state.slots}
async function renderSchedule(outlet){
  const mayViewOthers=canAny('schedule.viewOthers','schedule.manageOthers'),closers=state.data.users.filter(u=>u.role==='CLOSER'&&u.active);if(!state.scheduleCloserId)state.scheduleCloserId=mayViewOthers?(closers[0]?.id||state.data.me.id):state.data.me.id;if(!mayViewOthers)state.scheduleCloserId=state.data.me.id;const closerId=state.scheduleCloserId,slots=await loadScheduleSlots(closerId,state.slotDate,state.scheduleView),mayBuild=(closerId===state.data.me.id&&can('schedule.createOwnAvailability'))||can('schedule.manageOthers'),dates=state.scheduleView==='week'?Array.from({length:7},(_,i)=>shiftDate(state.slotDate,i)):[state.slotDate];
  const slotMarkup=s=>{const eventMarkup=event=>{const c=state.data.clients.find(item=>item.id===event.clientId)||(state.data.archivedClients||[]).find(item=>item.id===event.clientId),label=event.rescheduledTo?`Перенос → ${dateTime(event.rescheduledTo.scheduledAt)}`:(event.statusName||'Записан');return `<div class="booked-box ${event.active?'':'historical-event'}" ${c?`data-client="${c.id}"`:''}><div class="booked-slot-main"><div><b>${escapeHtml(c?.name||'Клиент')}</b><div class="booked-label">${escapeHtml(label)}</div>${c?`<div class="subline">${escapeHtml(c.normalizedPhone)}</div>`:''}</div>${c?avatars(c):''}</div></div>`},events=(s.events||[]);return `<div class="day-slot"><b>${time(s.startAt)}</b><div class="slot-event-stack">${events.map(eventMarkup).join('')}${s.status==='FREE'?'<div class="free-box">Свободно</div>':''}</div></div>`};
  outlet.innerHTML=`${pageHead('Доступность','Расписание','Опубликованные слоты доступны для записи; занятые слоты заблокированы.',mayBuild?'<button class="btn btn-primary" data-build>＋ Создать расписание</button>':'')}<div class="toolbar"><input class="chip" id="schedule-date" type="date" value="${state.slotDate}">${mayViewOthers?`<select class="chip" id="schedule-closer">${closers.map(u=>`<option value="${u.id}" ${u.id===closerId?'selected':''}>${escapeHtml(u.name)}</option>`).join('')}</select>`:''}<button class="chip ${state.scheduleView==='day'?'active':''}">День</button><button class="chip ${state.scheduleView==='week'?'active':''}">Неделя</button></div><div class="schedule-builder"><section class="panel"><div class="panel-head"><h2>Загрузка за ${state.scheduleView==='day'?'день':'неделю'}</h2></div><div class="metric-label">Занято: ${slots.filter(s=>s.status!=='FREE').length} · свободно: ${slots.filter(s=>s.status==='FREE').length}</div><div class="progress"><i style="width:${slots.length?slots.filter(s=>s.status!=='FREE').length/slots.length*100:0}%"></i></div><p class="subline">Существующие и занятые слоты защищены от перезаписи.</p></section><section class="schedule-days">${dates.map(date=>{const daySlots=slots.filter(s=>dayFromIso(s.startAt)===date);return `<div class="day-column"><div class="panel-head"><h2>${date}</h2><span class="subline">${daySlots.length} слотов</span></div>${daySlots.length?daySlots.map(slotMarkup).join(''):emptyState('Нет доступного времени','На эту дату слоты не опубликованы.','')}</div>`}).join('')}</section></div>`;
  bindClientClicks();outlet.querySelector('#schedule-date').onchange=e=>{state.slotDate=e.target.value;renderSchedule(outlet)};outlet.querySelector('#schedule-closer')?.addEventListener('change',e=>{state.scheduleCloserId=e.target.value;renderSchedule(outlet)});outlet.querySelector('[data-build]')?.addEventListener('click',()=>showScheduleBuilder(closerId));
}
function previewSchedule(form){const box=document.querySelector('#slot-preview'),start=form.start.value,end=form.end.value,interval=Number(form.interval.value),[sh,sm]=start.split(':').map(Number),[eh,em]=end.split(':').map(Number),values=[];let cursor=sh*60+sm;while(cursor+interval<=eh*60+em&&values.length<48){values.push(`${String(Math.floor(cursor/60)).padStart(2,'0')}:${String(cursor%60).padStart(2,'0')}`);cursor+=interval}box.innerHTML=values.length?`<div class="slots">${values.map(value=>`<span class="slot">${value}</span>`).join('')}</div><p class="subline">Будет создано до ${values.length} новых слотов. Дубликаты будут пропущены.</p>`:'<p class="overdue-label">Укажите корректный диапазон времени.</p>'}
function showScheduleBuilder(closerId=state.data.me.id){showModal(`<h2>Создать расписание</h2><p>Проверьте слоты перед сохранением. Существующие и занятые слоты останутся без изменений.</p><form id="builder"><input type="hidden" name="closerId" value="${closerId}"><div class="field"><label>Дата</label><input type="date" name="date" min="${today()}" value="${state.slotDate}" required></div><div class="form-grid"><div class="field"><label>Начало</label><input type="time" name="start" value="10:00" required></div><div class="field"><label>Конец</label><input type="time" name="end" value="18:00" required></div></div><div class="field"><label>Интервал</label><select name="interval"><option value="60">60 минут</option><option value="45">45 минут</option><option value="30">30 минут</option></select></div><div id="slot-preview"></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close-modal>Отмена</button><button class="btn btn-primary">Сохранить расписание</button></div></form>`);const form=document.querySelector('#builder');form.querySelectorAll('input,select').forEach(el=>el.addEventListener('input',()=>previewSchedule(form)));previewSchedule(form);form.onsubmit=async e=>{e.preventDefault();try{const result=await request('/api/slots/generate',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});closeModal();toast(result.created?`Создано слотов: ${result.created}`:'Новых слотов нет — дубликаты пропущены');renderSchedule(document.querySelector('#content'))}catch(err){toast(err.message,true)}}}

