const permissionLabels={view:'Просмотр',create:'Создание',edit:'Изменение',archive:'Архивирование',manage:'Управление',changeStatus:'Изменение статуса',addNotes:'Добавление заметок',viewHistory:'Просмотр истории',reassignManager:'Переназначение менеджера',reassignCloser:'Переназначение клоузера',createOwnAvailability:'Создание своей доступности',editOwnAvailability:'Изменение свободных слотов',viewOthers:'Просмотр чужих расписаний',manageOthers:'Управление чужими расписаниями',scheduleTrial:'Запись на пробный урок',rescheduleTrial:'Перенос пробного урока',viewManager:'Аналитика менеджеров',viewCloser:'Аналитика клоузеров',viewSource:'Аналитика источников',viewRefusal:'Аналитика отказов',export:'Экспорт в Excel',manageRoles:'Управление ролями',managePermissions:'Управление разрешениями',manageStatuses:'Статусы',manageRefusalReasons:'Причины отказа',manageLeadSources:'Источники лидов',managePaymentMethods:'Способы оплаты',manageTags:'Теги',manageBranding:'Брендинг'};
const scopeLabels={OWN:'Свои',TEAM:'Команда',ALL:'Все'};
function permissionEditor(values={},scopes={},overrides=false){return `<div class="permission-grid">${Object.entries(state.data.permissionCatalog).map(([module,actions])=>`<section class="permission-module"><h3>${moduleLabels[module]}</h3>${actions.map(action=>{const key=`${module}.${action}`,value=values[key];return `<label class="permission-option"><span>${permissionLabels[action]||action}</span>${overrides?`<select data-permission="${key}"><option value="" ${value===undefined?'selected':''}>По роли</option><option value="true" ${value===true?'selected':''}>Разрешить</option><option value="false" ${value===false?'selected':''}>Запретить</option></select>`:`<input type="checkbox" data-permission="${key}" ${value?'checked':''}>`}</label>`}).join('')}${['clients','schedule','payments','analytics'].includes(module)?`<label class="permission-option"><span>Область данных</span><select data-scope="${module}">${overrides?'<option value="">По роли</option>':''}${Object.entries(scopeLabels).map(([key,label])=>`<option value="${key}" ${scopes[module]===key?'selected':''}>${label}</option>`).join('')}</select></label>`:''}</section>`).join('')}</div>`}
function collectAccess(form,overrides=false){const permissions={},scopes={};form.querySelectorAll('[data-permission]').forEach(el=>{permissions[el.dataset.permission]=overrides?(el.value===''?null:el.value==='true'):el.checked});form.querySelectorAll('[data-scope]').forEach(el=>{scopes[el.dataset.scope]=overrides&&el.value===''?null:el.value});return{permissions,scopes}}
function fileData(file){return new Promise((resolve,reject)=>{if(!file)return resolve('');if(!['image/png','image/jpeg','image/webp','image/svg+xml'].includes(file.type))return reject(new Error('Используйте PNG, JPEG или WebP'));if(file.size>1_000_000)return reject(new Error('Размер изображения не должен превышать 1 МБ'));const reader=new FileReader();reader.onload=()=>typeof reader.result==='string'&&reader.result.startsWith('data:image/')?resolve(reader.result):reject(new Error('Некорректный файл изображения'));reader.onerror=()=>reject(new Error('Не удалось прочитать изображение'));reader.readAsDataURL(file)})}
function cropAvatarFile(file){return new Promise((resolve,reject)=>{if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type))return reject(new Error('Используйте PNG, JPEG или WebP'));if(file.size>8_000_000)return reject(new Error('Размер исходного фото не должен превышать 8 МБ'));const url=URL.createObjectURL(file),image=new Image();image.onload=()=>{let zoom=1,offsetX=0,offsetY=0,drag=null;document.body.insertAdjacentHTML('beforeend',`<div class="scrim avatar-crop-scrim"></div><section class="modal avatar-crop-modal"><h2>Настройте фото</h2><p>Перетаскивайте изображение и выберите масштаб. В круге показан будущий аватар.</p><canvas width="512" height="512" class="avatar-crop-canvas"></canvas><div class="field"><label>Масштаб</label><input type="range" min="1" max="3" step="0.01" value="1" data-crop-zoom></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-crop-cancel>Отмена</button><button type="button" class="btn btn-primary" data-crop-save>Использовать фото</button></div></section>`);const modal=document.querySelector('.avatar-crop-modal'),scrim=document.querySelector('.avatar-crop-scrim'),canvas=modal.querySelector('canvas'),ctx=canvas.getContext('2d'),cleanup=()=>{URL.revokeObjectURL(url);modal.remove();scrim.remove()},draw=()=>{const l=MiltonAvatarCrop.layout(image.width,image.height,zoom,offsetX,offsetY,512);offsetX=l.offsetX;offsetY=l.offsetY;ctx.clearRect(0,0,512,512);ctx.drawImage(image,l.x,l.y,l.width,l.height)};draw();modal.querySelector('[data-crop-zoom]').oninput=e=>{zoom=Number(e.target.value);draw()};canvas.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,offsetX,offsetY};canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag)return;const ratio=512/canvas.getBoundingClientRect().width;offsetX=drag.offsetX+(e.clientX-drag.x)*ratio;offsetY=drag.offsetY+(e.clientY-drag.y)*ratio;draw()};canvas.onpointerup=()=>{drag=null};modal.querySelector('[data-crop-cancel]').onclick=()=>{cleanup();reject(new Error('Выбор фото отменён'))};modal.querySelector('[data-crop-save]').onclick=()=>{const result=canvas.toDataURL('image/jpeg',.9);cleanup();resolve(result)}};image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Не удалось открыть изображение'))};image.src=url})}
function renderUsers(outlet){const users=state.data.users;outlet.innerHTML=`${pageHead('Сотрудники','Учётные записи команды','Роль задаёт права по умолчанию, а индивидуальные настройки имеют приоритет.',can('users.create')?'<button class="btn btn-primary" data-add-user>＋ Добавить сотрудника</button>':'')}<div class="table-wrap"><table><thead><tr><th>Сотрудник</th><th>Роль</th><th>Логин</th><th>Статус профиля</th><th>Доступ</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td><div class="client-cell">${avatar(u,roleLabel(u.role))}<b>${escapeHtml(u.name)}</b>${u.isOwner?'<span class="archive-badge">Владелец</span>':''}</div></td><td>${escapeHtml(state.data.roles.find(r=>r.id===u.roleId)?.name||roleLabel(u.role))}</td><td>${escapeHtml(u.login)}</td><td>${profileStatusLabel(u.profileStatus)}</td><td>${u.active?'<span class="status-pill" style="--status:#14a06f">Активен</span>':'<span class="status-pill" style="--status:#888">В архиве</span>'}</td><td>${can('users.edit')&&(!u.isOwner||state.data.me.isOwner)?`<button class="btn btn-ghost" data-edit-user="${u.id}">Настроить</button>`:''}${can('users.archive')&&u.active&&!u.isOwner&&u.id!==state.data.me.id?` <button class="btn btn-danger" data-archive-user="${u.id}">В архив</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;outlet.querySelector('[data-add-user]')?.addEventListener('click',()=>showUserModal());outlet.querySelectorAll('[data-edit-user]').forEach(btn=>btn.onclick=()=>showUserModal(users.find(u=>u.id===btn.dataset.editUser)));outlet.querySelectorAll('[data-archive-user]').forEach(btn=>btn.onclick=async()=>{try{await request(`/api/admin/users/${btn.dataset.archiveUser}/archive`,{method:'POST'});toast('Пользователь архивирован');await refreshData()}catch(err){toast(err.message,true)}})}
function showUserModal(account=null){const edit=Boolean(account);showModal(`<h2>${edit?'Настроить сотрудника':'Новый сотрудник'}</h2><p>Выберите роль и при необходимости задайте индивидуальные исключения.</p><form id="user-form"><div class="form-grid"><div class="field"><label>Имя *</label><input name="name" value="${escapeHtml(account?.name||'')}" required></div><div class="field"><label>Логин / контакт *</label><input name="login" value="${escapeHtml(account?.login||'')}" required></div>${edit?'':`<div class="field"><label>Пароль *</label><input name="password" type="password" minlength="6" required></div>`}<div class="field"><label>Роль *</label><select name="roleId">${state.data.roles.filter(r=>r.active).map(r=>`<option value="${r.id}" ${r.id===account?.roleId?'selected':''}>${escapeHtml(r.name)}</option>`).join('')}</select></div><div class="field"><label>Статус профиля</label><select name="profileStatus"><option value="WORKING">Работает</option><option value="DAY_OFF">Выходной</option><option value="NOT_ACCEPTING">Не принимает пробные уроки</option></select></div><div class="field"><label>Фото профиля</label><input name="avatar" type="file" accept="image/png,image/jpeg,image/webp"></div></div>${can('users.managePermissions')?`<h3>Индивидуальные разрешения</h3>${permissionEditor(account?.permissionOverrides||{},account?.scopeOverrides||{},true)}`:''}<div class="modal-actions"><button type="button" class="btn btn-ghost" data-close-modal>Отмена</button><button class="btn btn-primary">${edit?'Сохранить':'Создать аккаунт'}</button></div></form>`);const form=document.querySelector('#user-form');if(account)form.profileStatus.value=account.profileStatus;form.onsubmit=async e=>{e.preventDefault();try{const fd=new FormData(form),access=collectAccess(form,true),file=fd.get('avatar');const avatarUrl=file?.size?await fileData(file):(account?.avatarUrl||'');const payload={name:fd.get('name'),login:fd.get('login'),password:fd.get('password'),roleId:fd.get('roleId'),profileStatus:fd.get('profileStatus'),avatarUrl,permissionOverrides:access.permissions,scopeOverrides:access.scopes};await request(edit?`/api/admin/users/${account.id}`:'/api/admin/users',{method:edit?'PUT':'POST',body:JSON.stringify(payload)});closeModal();toast(edit?'Настройки сотрудника сохранены':'Сотрудник создан');await refreshData()}catch(err){toast(err.message,true)}}}
function showUserModalV2(account=null){const edit=Boolean(account);showModal(`<h2>${edit?'Настроить сотрудника':'Новый сотрудник'}</h2><p>Команда используется областями TEAM; пустое значение означает отсутствие команды.</p><form id="user-form-v2"><div class="form-grid"><div class="field"><label>Имя *</label><input name="name" value="${escapeHtml(account?.name||'')}" required></div><div class="field"><label>Логин *</label><input name="login" value="${escapeHtml(account?.login||'')}" required></div><div class="field"><label>${edit?'Новый пароль':'Пароль *'}</label><input name="password" type="password" minlength="6" ${edit?'placeholder="Без изменений"':'required'}></div><div class="field"><label>Роль *</label><select name="roleId">${state.data.roles.filter(r=>r.active).map(r=>`<option value="${r.id}" ${r.id===account?.roleId?'selected':''}>${escapeHtml(r.name)}</option>`).join('')}</select></div><div class="field"><label>Команда / Team ID</label><input name="teamId" value="${escapeHtml(account?.teamId||'')}" placeholder="Например: sales-a"></div><div class="field"><label>Статус профиля</label><select name="profileStatus"><option value="WORKING">Работает</option><option value="DAY_OFF">Выходной</option><option value="NOT_ACCEPTING">Не принимает пробные уроки</option></select></div><div class="field wide"><label>Фото профиля</label><input name="avatar" type="file" accept="image/png,image/jpeg,image/webp"><small class="subline" data-employee-avatar-state>${account?.avatarUrl?'Фото сохранено':'Фото не выбрано'}</small></div></div>${can('users.managePermissions')?`<h3>Индивидуальные разрешения</h3>${permissionEditor(account?.permissionOverrides||{},account?.scopeOverrides||{},true)}`:''}<div class="modal-actions"><button type="button" class="btn btn-ghost" data-close-modal>Отмена</button><button class="btn btn-primary">${edit?'Сохранить':'Создать аккаунт'}</button></div></form>`);const form=document.querySelector('#user-form-v2');let croppedAvatar=null;form.profileStatus.value=account?.profileStatus||'WORKING';form.avatar.onchange=async()=>{try{const file=form.avatar.files?.[0];if(!file)return;croppedAvatar=await cropAvatarFile(file);form.querySelector('[data-employee-avatar-state]').textContent='Кадрирование готово'}catch(err){form.avatar.value='';croppedAvatar=null;if(err.message!=='Выбор фото отменён')toast(err.message,true)}};form.onsubmit=async e=>{e.preventDefault();try{const fd=new FormData(form),access=collectAccess(form,true),avatarUrl=croppedAvatar??(account?.avatarUrl||''),payload={name:fd.get('name'),login:fd.get('login'),password:fd.get('password')||undefined,roleId:fd.get('roleId'),teamId:fd.get('teamId')||null,profileStatus:fd.get('profileStatus'),avatarUrl,permissionOverrides:access.permissions,scopeOverrides:access.scopes};await request(edit?`/api/admin/users/${account.id}`:'/api/admin/users',{method:edit?'PUT':'POST',body:JSON.stringify(payload)});closeModal();toast(edit?'Настройки сотрудника сохранены':'Сотрудник создан');await refreshData()}catch(err){toast(err.message,true)}}}
function showEmployeeDeleteModal(account){const reassignmentRole=['MANAGER','CLOSER'].includes(account.role),candidates=state.data.users.filter(user=>user.id!==account.id&&user.active&&user.role===account.role),clients=[...(state.data.clients||[]),...(state.data.archivedClients||[])],affected=clients.filter(client=>account.role==='MANAGER'?(client.currentManagerId===account.id||client.originalManagerId===account.id):account.role==='CLOSER'?client.currentCloserId===account.id:false).length,needsReplacement=reassignmentRole&&affected>0;showModal(`<div class="destructive-heading"><span>!</span><div><h2>Удалить сотрудника навсегда?</h2><p>Профиль «${escapeHtml(account.name)}», права, слоты и все созданные или атрибутированные ему записи будут удалены из CRM и аналитики.</p></div></div><div class="danger-notice">Оплаты, уроки, заметки и события этого сотрудника восстановить будет невозможно.</div><form id="employee-delete-form">${needsReplacement?`<div class="field"><label>Передать клиентов сотруднику · клиентов: ${affected}</label><select name="replacementUserId" required>${candidates.length?candidates.map((user,index)=>`<option value="${user.id}" ${index===0?'selected':''}>${escapeHtml(user.name)}</option>`).join(''):'<option value="">Нет активного сотрудника той же роли</option>'}</select><small>${candidates.length?'Сотрудник уже выбран автоматически. При необходимости выберите другого.':'Сначала создайте или восстановите сотрудника той же роли.'}</small></div>`:'<p class="subline employee-no-clients">У сотрудника нет назначенных клиентов — передача не требуется.</p>'}<div class="modal-actions"><button type="button" class="btn btn-ghost" data-close-modal>Отмена</button><button type="submit" class="btn btn-danger" ${needsReplacement&&!candidates.length?'disabled':''}>Удалить навсегда</button></div></form>`);const form=document.querySelector('#employee-delete-form');form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button[type="submit"]'),replacementUserId=new FormData(form).get('replacementUserId')||null;button.disabled=true;button.textContent='Удаляем…';try{const result=await request(`/api/admin/users/${account.id}`,{method:'DELETE',body:JSON.stringify({confirmed:true,replacementUserId})});closeModal();toast(result.relatedRecordsRemoved.clientsReassigned?`Сотрудник удалён · клиентов передано: ${result.relatedRecordsRemoved.clientsReassigned}`:'Сотрудник удалён');await refreshData()}catch(err){button.disabled=false;button.textContent='Удалить навсегда';toast(err.message,true)}}}
function renderRoles(outlet){const roles=state.data.roles;outlet.innerHTML=`${pageHead('Контроль доступа','Роли и разрешения','Системные роли сохраняются, пользовательские можно архивировать.','<button class="btn btn-primary" data-add-role>＋ Новая роль</button>')}<div class="settings-grid">${roles.map(role=>`<section class="panel"><div class="panel-head"><div><h2>${escapeHtml(role.name)}</h2><div class="subline">${role.isSystem?'Системный шаблон':'Пользовательская роль'} · ${role.active?'Активна':'В архиве'}</div></div><button class="btn btn-ghost" data-role="${role.id}">Настроить</button></div><div class="subline">Разрешено: ${Object.values(role.permissions).filter(Boolean).length} · Клиенты: ${scopeLabels[role.scopes.clients]}</div></section>`).join('')}</div>`;outlet.querySelector('[data-add-role]').onclick=()=>showRoleModal();outlet.querySelectorAll('[data-role]').forEach(btn=>btn.onclick=()=>showRoleModal(roles.find(r=>r.id===btn.dataset.role)))}
function showRoleModal(role=null){const edit=Boolean(role),permissions=role?.permissions||{};showModal(`<h2>${edit?'Настройка роли':'Новая роль'}</h2><p>Разрешения роли применяются ко всем пользователям без индивидуального переопределения.</p><form id="role-form"><div class="form-grid"><div class="field"><label>Название *</label><input name="name" value="${escapeHtml(role?.name||'')}" required></div>${edit?'':`<div class="field"><label>Базовый тип</label><select name="baseRole"><option value="MANAGER">Менеджер</option><option value="CLOSER">Клоузер</option><option value="ADMIN">Администратор</option></select></div>`}</div>${permissionEditor(permissions,role?.scopes||{},false)}<div class="modal-actions">${edit&&!role.isSystem?'<button type="button" class="btn btn-danger" data-archive-role>Архивировать</button>':''}<button type="button" class="btn btn-ghost" data-close-modal>Отмена</button><button class="btn btn-primary">Сохранить</button></div></form>`);const form=document.querySelector('#role-form');form.onsubmit=async e=>{e.preventDefault();try{const access=collectAccess(form),fd=new FormData(form);await request(edit?`/api/admin/roles/${role.id}`:'/api/admin/roles',{method:edit?'PUT':'POST',body:JSON.stringify({name:fd.get('name'),baseRole:fd.get('baseRole'),permissions:access.permissions,scopes:access.scopes})});closeModal();toast('Роль сохранена');await refreshData()}catch(err){toast(err.message,true)}};form.querySelector('[data-archive-role]')?.addEventListener('click',async()=>{try{await request(`/api/admin/roles/${role.id}/archive`,{method:'POST'});closeModal();toast('Роль архивирована');await refreshData()}catch(err){toast(err.message,true)}})}
function analyticsDimensions(){return state.data.analyticsDimensions||state.data}
function analyticsFilterItems(){
  const f=state.analyticsFilters,d=analyticsDimensions(),find=(list,id)=>displayName((list||[]).find(x=>x.id===id));
  const chips=[{key:'period',text:`${f.from} — ${f.to}`}];
  if(f.managerId)chips.push({key:'managerId',text:`Менеджер: ${(d.users||[]).find(u=>u.id===f.managerId)?.name||'Архивный сотрудник'}`});
  if(f.closerId)chips.push({key:'closerId',text:`Клоузер: ${(d.users||[]).find(u=>u.id===f.closerId)?.name||'Архивный сотрудник'}`});
  if(f.sourceId)chips.push({key:'sourceId',text:`Источник: ${find(d.leadSources,f.sourceId)}`});
  if(f.statusId)chips.push({key:'statusId',text:`Статус: ${find(d.statuses,f.statusId)}`});
  if(f.paymentMethodId)chips.push({key:'paymentMethodId',text:`Оплата: ${find(d.paymentMethods,f.paymentMethodId)}`});
  if(f.refusalReasonId)chips.push({key:'refusalReasonId',text:`Отказ: ${find(d.refusalReasons,f.refusalReasonId)}`});
  if(f.tagId)chips.push({key:'tagId',text:`Тег: ${find(d.tags,f.tagId)}`});
  if(f.compare)chips.push({key:'compare',text:'Сравнение периодов'});
  if(f.includeArchived)chips.push({key:'includeArchived',text:'Включая архив'});
  return chips;
}
function analyticsFilterChips(){return analyticsFilterItems().map(chip=>`<button class="filter-chip" data-clear-filter="${chip.key}">${escapeHtml(chip.text)} <b>×</b></button>`).join('')}
function analyticsCompactSummary(){
  const items=analyticsFilterItems(),primary=items.filter(item=>['period','managerId','closerId'].includes(item.key)),extra=Math.max(0,items.length-primary.length);
  return `${primary.map(item=>`<span>${escapeHtml(item.text)}</span>`).join('')}${extra?`<span class="compact-more">+${extra} ещё</span>`:''}`;
}
function analyticsFilterBar(){
  const f=state.analyticsFilters,d=analyticsDimensions(),option=(items,value)=>items.map(item=>`<option value="${item.id}" ${value===item.id?'selected':''}>${escapeHtml(displayName(item))}${item.active===false?' · архив':''}</option>`).join(''),users=d.users||[];
  const activeCount=Math.max(0,analyticsFilterItems().length-1);
  const full=`<div class="analytics-filter-full"><div class="analytics-filter-head"><b>Фильтры аналитики</b><button class="icon-btn filter-close" data-filter-close aria-label="Свернуть фильтры">×</button></div><div class="analytics-filter-grid"><div class="field"><label>Период</label><select data-af="preset"><option value="today" ${f.preset==='today'?'selected':''}>Сегодня</option><option value="yesterday" ${f.preset==='yesterday'?'selected':''}>Вчера</option><option value="week" ${f.preset==='week'?'selected':''}>Эта неделя</option><option value="previousWeek" ${f.preset==='previousWeek'?'selected':''}>Предыдущая неделя</option><option value="month" ${f.preset==='month'?'selected':''}>Этот месяц</option><option value="previousMonth" ${f.preset==='previousMonth'?'selected':''}>Предыдущий месяц</option><option value="custom" ${f.preset==='custom'?'selected':''}>Произвольный период</option></select></div><div class="field custom-date ${f.preset!=='custom'?'hidden':''}"><label>Дата от</label><input data-af="from" type="date" value="${f.from}"></div><div class="field custom-date ${f.preset!=='custom'?'hidden':''}"><label>Дата до</label><input data-af="to" type="date" value="${f.to}"></div><div class="field"><label>Когорта текущих статусов</label><select data-af="dateType"><option value="client" ${f.dateType==='client'?'selected':''}>Создание клиента</option><option value="trial" ${f.dateType==='trial'?'selected':''}>Пробный урок</option><option value="payment" ${f.dateType==='payment'?'selected':''}>Оплата</option></select></div><div class="field"><label>Менеджер</label><select data-af="managerId"><option value="">Все менеджеры</option>${users.filter(u=>u.role==='MANAGER').map(u=>`<option value="${u.id}" ${f.managerId===u.id?'selected':''}>${escapeHtml(u.name)}${u.active===false?' · архив':''}</option>`).join('')}</select></div><div class="field"><label>Клоузер</label><select data-af="closerId"><option value="">Все клоузеры</option>${users.filter(u=>u.role==='CLOSER').map(u=>`<option value="${u.id}" ${f.closerId===u.id?'selected':''}>${escapeHtml(u.name)}${u.active===false?' · архив':''}</option>`).join('')}</select></div><div class="field"><label>Источник лида</label><select data-af="sourceId"><option value="">Все источники</option>${option(d.leadSources,f.sourceId)}</select></div><div class="field"><label>CRM-статус</label><select data-af="statusId"><option value="">Все статусы</option>${option(d.statuses,f.statusId)}</select></div><div class="field"><label>Способ оплаты</label><select data-af="paymentMethodId"><option value="">Все способы</option>${option(d.paymentMethods,f.paymentMethodId)}</select></div><div class="field"><label>Причина отказа</label><select data-af="refusalReasonId"><option value="">Все причины</option>${option(d.refusalReasons,f.refusalReasonId)}</select></div><div class="field"><label>Тег клиента</label><select data-af="tagId"><option value="">Все теги</option>${option(d.tags,f.tagId)}</select></div></div><div class="filter-footer"><div class="analytics-toggles"><label class="compare-toggle"><input data-af="compare" type="checkbox" ${f.compare?'checked':''}> Сравнить с предыдущим периодом</label>${can('clients.archive')?`<label class="compare-toggle"><input data-af="includeArchived" type="checkbox" ${f.includeArchived?'checked':''}> Включить архивных клиентов</label>`:''}</div><button class="btn btn-ghost" data-reset-analytics>Сбросить фильтры</button></div><div class="active-filters">${analyticsFilterChips()}</div></div>`;
  return `<div class="analytics-filter-scrim ${state.analyticsUi.drawerOpen?'open':''}" data-filter-close></div><section class="analytics-filter ${state.analyticsUi.collapsed?'collapsed':''} ${state.analyticsUi.drawerOpen?'drawer-open':''}"><div class="analytics-filter-compact"><button class="btn btn-ghost filter-expand" data-filter-expand aria-expanded="${!state.analyticsUi.collapsed}">⚙ <span class="desktop-filter-label">Фильтры${activeCount?` · ${activeCount}`:''}</span></button><div class="compact-summary">${analyticsCompactSummary()}</div><button class="btn btn-ghost compact-reset" data-reset-analytics>Сбросить</button></div>${full}</section>`;
}
function analyticsQuery(){const params=new URLSearchParams();Object.entries(state.analyticsFilters).forEach(([key,value])=>{if(key!=='preset'&&value!==''&&value!==false)params.set(key,String(value))});return params.toString()}
function deltaMarkup(current,previous,type='percent'){if(previous===undefined||previous===null)return'';if(previous===0)return `<small class="kpi-delta neutral">Нет сопоставимых данных</small>`;const change=type==='points'?current-previous:(current-previous)/Math.abs(previous)*100,up=change>=0;return `<small class="kpi-delta ${up?'up':'down'}">${up?'↑':'↓'} ${Math.abs(change).toFixed(1)}${type==='points'?' п.п.':'%'}</small>`}
function analyticsLineChart(rows,series){if(!rows.length)return emptyState('Нет данных за выбранный период','Измените даты или другие фильтры.','');const width=680,height=190,pad=28,max=Math.max(1,...rows.flatMap(row=>series.map(item=>Number(row[item.key]||0)))),x=i=>rows.length===1?width/2:pad+i*(width-pad*2)/(rows.length-1),y=v=>height-pad-(Number(v)/max)*(height-pad*2);return `<div class="line-chart"><svg viewBox="0 0 ${width} ${height}" role="img">${[0,.5,1].map(t=>`<line x1="${pad}" y1="${y(max*t)}" x2="${width-pad}" y2="${y(max*t)}" class="grid-line"/>`).join('')}${series.map(item=>`<polyline points="${rows.map((row,i)=>`${x(i)},${y(row[item.key])}`).join(' ')}" fill="none" stroke="${item.color}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${rows.map((row,i)=>`<circle cx="${x(i)}" cy="${y(row[item.key])}" r="4" fill="${item.color}"><title>${row.key}: ${item.label} — ${item.money?money(row[item.key]):row[item.key]}</title></circle>`).join('')}`).join('')}</svg><div class="chart-axis">${rows.map((row,i)=>i%Math.max(1,Math.ceil(rows.length/6))===0?`<span>${escapeHtml(row.key)}</span>`:'').join('')}</div><div class="chart-legend">${series.map(item=>`<span><i style="background:${item.color}"></i>${item.label}</span>`).join('')}</div></div>`}
function horizontalChart(rows,nameFn=(row)=>displayName(row)){if(!rows.length)return emptyState('Нет данных за выбранный период','Для выбранных фильтров нет подходящих записей.','');const max=Math.max(1,...rows.map(row=>row.count||row.revenue||0));return `<div class="horizontal-chart">${rows.map(row=>{const value=row.count??row.revenue??0;return `<div class="hbar-row" title="${escapeHtml(nameFn(row))}: ${value}${row.percentage!==undefined?` · ${row.percentage.toFixed(1)}%`:''}"><span>${escapeHtml(nameFn(row))}</span><div class="hbar-track"><i style="width:${value/max*100}%;background:${row.color||'var(--accent)'}"></i></div><b>${value}</b>${row.percentage!==undefined?`<small>${row.percentage.toFixed(1)}%</small>`:''}</div>`}).join('')}</div>`}
function donutChart(rows){const meaningful=rows.filter(row=>row.count>0);if(!meaningful.length||meaningful.length>6)return'';let cursor=0;const parts=meaningful.map(row=>{const start=cursor;cursor+=row.percentage;return `${row.color} ${start}% ${cursor}%`});return `<div class="donut-block"><div class="donut" style="background:conic-gradient(${parts.join(',')})"><span><b>${meaningful.reduce((sum,row)=>sum+row.count,0)}</b><small>клиентов</small></span></div><div class="donut-legend">${meaningful.map(row=>`<span><i style="background:${row.color}"></i>${escapeHtml(displayName(row))} <b>${row.percentage.toFixed(1)}%</b></span>`).join('')}</div></div>`}
function performanceTable(kind,rows){const sort=state.analyticsSort[kind],sorted=[...rows].sort((a,b)=>(b[sort]||0)-(a[sort]||0)),closer=kind==='closers';return `<div class="panel-head"><h2>${closer?'Клоузеры':'Менеджеры'}</h2><select class="chip" data-analytics-sort="${kind}"><option value="revenue" ${sort==='revenue'?'selected':''}>По выручке</option><option value="conversion" ${sort==='conversion'?'selected':''}>По конверсии</option><option value="payments" ${sort==='payments'?'selected':''}>По оплатам</option><option value="trials" ${sort==='trials'?'selected':''}>По урокам</option></select></div>${sorted.length?`<div class="table-wrap analytics-table"><table><thead><tr><th>${closer?'Клоузер':'Менеджер'}</th>${closer?'<th>Проведено</th>':'<th>Клиенты</th>'}<th>Уроки</th><th>Оплаты</th><th>Конверсия</th><th>Выручка</th><th>Средний чек</th></tr></thead><tbody>${sorted.map(row=>`<tr><td><b>${escapeHtml(row.name)}</b></td><td>${closer?row.conducted:row.clients}</td><td>${row.trials}</td><td>${row.payments}</td><td>${row.conversion.toFixed(1)}%</td><td class="money">${money(row.revenue)}</td><td>${money(Math.round(row.average))}</td></tr>`).join('')}</tbody></table></div>`:emptyState('Нет данных','За период нет показателей сотрудников.','')}`}
async function renderAnalytics(outlet){if(!state.analyticsFilters){state.analyticsFilters=defaultAnalyticsFilters()}outlet.innerHTML=`${pageHead('Показатели бизнеса','Аналитика',state.data.me.role==='ADMIN'?'Все показатели рассчитаны на сервере с учётом области доступа.':'Показаны только данные, разрешённые вашей областью доступа.')} ${analyticsFilterBar()}<div id="analytics-results"><div class="analytics-skeleton">${'<i></i>'.repeat(10)}</div></div>`;bindAnalyticsFilters(outlet);setupAnalyticsSticky(outlet);await loadAnalytics(outlet)}
async function loadAnalytics(outlet){const result=outlet.querySelector('#analytics-results');if(!result)return;result.innerHTML=`<div class="analytics-skeleton">${'<i></i>'.repeat(10)}</div>`;try{state.analyticsReport=await request(`/api/analytics?${analyticsQuery()}`);renderAnalyticsReport(result,state.analyticsReport);enhanceAnalyticsReport(result,state.analyticsReport)}catch(err){result.innerHTML=emptyState('Не удалось загрузить аналитику',err.message,'')}}
function renderAnalyticsReport(outlet,a){const k=a.kpis,p=a.comparison?.kpis||{},noData=!k.trials&&!k.payments&&!a.statuses.some(row=>row.count),exportUrl=`/api/export/analytics.csv?${analyticsQuery()}`;outlet.innerHTML=`<div class="analytics-section-head"><div><div class="eyebrow">Ключевые показатели</div><h2>${a.filters.from} — ${a.filters.to}</h2></div>${can('analytics.export')?`<a class="btn btn-ghost" href="${exportUrl}" target="_blank">Экспорт аналитики</a>`:''}</div><section class="analytics-kpis"><div class="metric"><span class="metric-label">Пробные уроки</span><strong>${k.trials}</strong>${a.comparison?deltaMarkup(k.trials,p.trials):''}</div><div class="metric"><span class="metric-label">Оплаты / чеки</span><strong>${k.payments}</strong>${a.comparison?deltaMarkup(k.payments,p.payments):''}</div><div class="metric"><span class="metric-label">Конверсия урок → оплата</span><strong>${k.conversion.toFixed(1)}%</strong>${a.comparison?deltaMarkup(k.conversion,p.conversion,'points'):''}</div><div class="metric"><span class="metric-label">Выручка</span><strong>${money(k.revenue)}</strong>${a.comparison?deltaMarkup(k.revenue,p.revenue):''}</div><div class="metric"><span class="metric-label">Средний чек</span><strong>${money(Math.round(k.average))}</strong>${a.comparison?deltaMarkup(k.average,p.average):''}</div></section>${a.comparison?`<p class="comparison-note">Сравнение с периодом ${a.comparison.from} — ${a.comparison.to}. Изменение конверсии показано в процентных пунктах.</p>`:''}${noData?emptyState('Нет данных за выбранный период','Измените период или снимите часть фильтров.',''):`<section class="analytics-grid status-section"><div class="panel"><div class="panel-head"><div><h2>Статусы воронки</h2><div class="subline">База: ${a.statusBaseline.count} — ${a.statusBaseline.label}</div></div></div>${horizontalChart(a.statuses,row=>displayName(row))}</div>${a.statuses.filter(row=>row.count).length<=6?`<div class="panel"><div class="panel-head"><h2>Распределение результатов</h2></div>${donutChart(a.statuses)}</div>`:''}</section><section class="analytics-grid"><div class="panel"><div class="panel-head"><h2>Пробные уроки и оплаты</h2><span class="subline">Группировка: ${a.granularity==='day'?'по дням':a.granularity==='week'?'по неделям':'по месяцам'}</span></div>${analyticsLineChart(a.trend,[{key:'trials',label:'Пробные уроки',color:'var(--accent)'},{key:'payments',label:'Оплаты',color:'#14a06f'}])}</div><div class="panel"><div class="panel-head"><h2>Динамика выручки</h2><span class="subline">Только по фактической дате оплаты</span></div>${analyticsLineChart(a.trend,[{key:'revenue',label:'Выручка',color:'#8b5cf6',money:true}])}</div></section>${a.managers.length||a.closers.length?`<div class="analytics-section-head"><div><div class="eyebrow">Эффективность команды</div><h2>Менеджеры и клоузеры</h2></div></div><section class="analytics-grid performance-grid">${a.managers.length?`<div class="panel">${performanceTable('managers',a.managers)}</div>`:''}${a.closers.length?`<div class="panel">${performanceTable('closers',a.closers)}</div>`:''}</section>`:''}<div class="analytics-section-head"><div><div class="eyebrow">Детализация</div><h2>Причины, источники и способы оплаты</h2></div></div><section class="analytics-grid breakdown-grid">${a.refusals.length?`<div class="panel"><div class="panel-head"><h2>Причины отказа</h2></div>${horizontalChart(a.refusals,row=>displayName(row))}</div>`:''}${a.paymentMethods.length?`<div class="panel"><div class="panel-head"><h2>Способы оплаты</h2></div><div class="breakdown-list">${a.paymentMethods.map(row=>`<div><span><b>${escapeHtml(displayName(row))}</b><small>${row.payments} оплат · ${row.share.toFixed(1)}% выручки</small></span><strong>${money(row.revenue)}</strong></div>`).join('')}</div></div>`:''}${a.sources.length?`<div class="panel sources-panel"><div class="panel-head"><h2>Источники лидов</h2><select class="chip" data-analytics-sort="sources"><option value="revenue">По выручке</option><option value="conversion">По конверсии</option><option value="payments">По оплатам</option><option value="trials">По урокам</option></select></div><div class="table-wrap analytics-table"><table><thead><tr><th>Источник</th><th>Клиенты</th><th>Уроки</th><th>Оплаты</th><th>Конверсия</th><th>Выручка</th><th>Средний чек</th></tr></thead><tbody>${[...a.sources].sort((x,y)=>(y[state.analyticsSort.sources]||0)-(x[state.analyticsSort.sources]||0)).map(row=>`<tr><td><b>${escapeHtml(displayName(row))}</b></td><td>${row.clients}</td><td>${row.trials}</td><td>${row.payments}</td><td>${row.conversion.toFixed(1)}%</td><td class="money">${money(row.revenue)}</td><td>${money(Math.round(row.average))}</td></tr>`).join('')}</tbody></table></div></div>`:''}</section>`}`;outlet.querySelectorAll('[data-analytics-sort]').forEach(select=>select.onchange=()=>{state.analyticsSort[select.dataset.analyticsSort]=select.value;renderAnalyticsReport(outlet,a)})}
function enhanceAnalyticsReport(outlet,a){
  const sectionHead=outlet.querySelector('.analytics-section-head');if(sectionHead&&can('analytics.export')){const actions=document.createElement('div');actions.className='export-actions';actions.innerHTML=`<a class="btn btn-ghost" href="/api/export/trials.csv?${analyticsQuery()}" target="_blank">Уроки CSV</a><a class="btn btn-ghost" href="/api/export/payments.csv?${analyticsQuery()}" target="_blank">Оплаты CSV</a><a class="btn btn-ghost" href="/api/export/clients.csv?${analyticsQuery()}" target="_blank">Клиенты CSV</a>`;sectionHead.append(actions)}
  const metrics=outlet.querySelector('.analytics-kpis');
  if(metrics&&a.kpis.trialClients!==undefined){
    const first=metrics.querySelector('.metric');
    first?.querySelector('.metric-label')?.replaceChildren('Пробные уроки (события)');
    const unique=document.createElement('div');unique.className='metric';unique.innerHTML=`<span class="metric-label">Уникальные клиенты с уроком</span><strong>${Number(a.kpis.trialClients)||0}</strong>${a.comparison?deltaMarkup(a.kpis.trialClients,a.comparison.kpis.trialClients):''}`;first?.after(unique);
  }
  if(metrics&&a.attendance){const at=a.attendance,block=document.createElement('section');block.className='panel attendance-panel';block.innerHTML=`<div class="panel-head"><div><div class="eyebrow">Доходимость</div><h2>Результат назначенных пробных уроков</h2></div><strong class="attendance-rate">${Number(at.attendance||0).toFixed(1)}%</strong></div><div class="attendance-kpis"><div><span>Назначено</span><b>${at.scheduled}</b></div><div><span>Дошли</span><b>${at.reached}</b></div><div><span>Неявка</span><b>${at.noShow}</b></div><div><span>Перенос</span><b>${at.rescheduled}</b></div><div class="${at.unresolvedOverdue?'attendance-overdue':''}"><span>Просрочено без результата</span><b>${at.unresolvedOverdue}</b></div></div><div class="attendance-progress"><i style="width:${Math.max(0,Math.min(100,Number(at.attendance||0)))}%"></i></div><p class="subline">Дошли = назначено − неявка − перенос. Просроченные без результата показаны отдельно и временно исключены из подтверждённой доходимости.</p>`;metrics.after(block)}
  const statusHeading=[...outlet.querySelectorAll('h2')].find(el=>el.textContent==='Статусы воронки');if(statusHeading)statusHeading.textContent='Текущий статус уникальных клиентов';
  const trendHeading=[...outlet.querySelectorAll('h2')].find(el=>el.textContent==='Пробные уроки и оплаты');if(trendHeading)trendHeading.textContent='События пробных уроков и оплаты';
}
function setupAnalyticsSticky(outlet){
  const filter=outlet.querySelector('.analytics-filter');if(!filter)return;
  const apply=()=>{filter.classList.toggle('collapsed',state.analyticsUi.collapsed);filter.classList.toggle('drawer-open',state.analyticsUi.drawerOpen);outlet.querySelector('.analytics-filter-scrim')?.classList.toggle('open',state.analyticsUi.drawerOpen);document.body.classList.toggle('analytics-filter-open',state.analyticsUi.drawerOpen);};
  if(state.analyticsScrollHandler)window.removeEventListener('scroll',state.analyticsScrollHandler);
  state.analyticsScrollHandler=()=>{if(window.innerWidth<=600)return;const shouldCollapse=window.scrollY>150&&!state.analyticsUi.manualExpanded;if(shouldCollapse!==state.analyticsUi.collapsed){state.analyticsUi.collapsed=shouldCollapse;apply()}if(window.scrollY<80){state.analyticsUi.manualExpanded=false;if(state.analyticsUi.collapsed){state.analyticsUi.collapsed=false;apply()}}};
  window.addEventListener('scroll',state.analyticsScrollHandler,{passive:true});state.analyticsScrollHandler();
  outlet.querySelector('[data-filter-expand]')?.addEventListener('click',()=>{if(window.innerWidth<=600){state.analyticsUi.drawerOpen=true}else{state.analyticsUi.collapsed=false;state.analyticsUi.manualExpanded=true;window.scrollTo({top:0,behavior:'smooth'})}apply()});
  outlet.querySelectorAll('[data-filter-close]').forEach(btn=>btn.addEventListener('click',()=>{if(window.innerWidth<=600){state.analyticsUi.drawerOpen=false}else{state.analyticsUi.collapsed=true;state.analyticsUi.manualExpanded=false}apply()}));
}
function bindAnalyticsFilters(outlet){
  outlet.querySelectorAll('[data-af]').forEach(input=>input.onchange=async()=>{const key=input.dataset.af;if(key==='preset'){state.analyticsFilters.preset=input.value;if(input.value!=='custom')Object.assign(state.analyticsFilters,analyticsPeriod(input.value));else outlet.querySelectorAll('.custom-date').forEach(el=>el.classList.remove('hidden'))}else if(['compare','includeArchived'].includes(key))state.analyticsFilters[key]=input.checked;else{state.analyticsFilters[key]=input.value;if(key==='from'||key==='to')state.analyticsFilters.preset='custom'}await renderAnalytics(outlet)});
  outlet.querySelectorAll('[data-reset-analytics]').forEach(btn=>btn.onclick=async()=>{state.analyticsFilters=defaultAnalyticsFilters();await renderAnalytics(outlet)});
  outlet.querySelectorAll('[data-clear-filter]').forEach(btn=>btn.onclick=async()=>{const key=btn.dataset.clearFilter;if(key==='period')Object.assign(state.analyticsFilters,{preset:'month',...analyticsPeriod('month')});else if(['compare','includeArchived'].includes(key))state.analyticsFilters[key]=false;else state.analyticsFilters[key]='';await renderAnalytics(outlet)});
}
function renderSettings(outlet){const d=state.data;const block=(title,items)=>`<section class="panel"><div class="panel-head"><h2>${title}</h2><button class="link">＋ Добавить</button></div><ul class="config-list">${items.sort((a,b)=>(a.sortOrder||0)-(b.sortOrder||0)).map(x=>`<li><span>${x.color?`<i style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${x.color};margin-right:8px"></i>`:''}<b>${escapeHtml(displayName(x))}</b>${x.actionType&&x.actionType!=='NONE'?`<div class="subline">${actionTypeLabel(x.actionType)}</div>`:''}</span><span class="subline">${x.active?'Активен':'В архиве'} · ⋮</span></li>`).join('')}</ul></section>`;outlet.innerHTML=`${pageHead('Администрирование','Настройки CRM','Брендинг и справочники управляются отдельными разрешениями.')}<div class="settings-grid">${can('settings.manageStatuses')?block('Статусы',d.statuses):''}${can('settings.manageLeadSources')?block('Источники лидов',d.leadSources):''}${can('settings.manageRefusalReasons')?block('Причины отказа',d.refusalReasons):''}${can('settings.managePaymentMethods')?block('Способы оплаты',d.paymentMethods):''}${can('settings.manageTags')?block('Теги клиентов',d.tags):''}${can('settings.manageBranding')?`<section class="panel"><div class="panel-head"><h2>Брендинг</h2><span class="subline">Сохраняется в базе данных</span></div><form id="branding-form"><div style="display:flex;gap:16px;align-items:center;margin-bottom:16px">${d.branding.logoUrl?`<img class="logo-preview" src="${escapeHtml(d.branding.logoUrl)}" alt="Логотип">`:'<span class="brand-mark">M</span>'}<div class="field" style="margin:0;flex:1"><label>Логотип компании</label><input name="logo" type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml"></div></div><div class="field"><label>Название компании</label><input name="companyName" value="${escapeHtml(d.branding.companyName)}" required></div><div class="field"><label>Акцентный цвет</label><input name="accentColor" type="color" value="${d.branding.accentColor}"></div><button class="btn btn-primary">Сохранить брендинг</button></form></section>`:''}</div>`;const form=outlet.querySelector('#branding-form');if(form)form.onsubmit=async e=>{e.preventDefault();try{const fd=new FormData(form),file=fd.get('logo'),logoUrl=file?.size?await fileData(file):d.branding.logoUrl;await request('/api/admin/branding',{method:'PUT',body:JSON.stringify({companyName:fd.get('companyName'),accentColor:fd.get('accentColor'),logoUrl})});toast('Брендинг сохранён');await refreshData()}catch(err){toast(err.message,true)}}}
const configUi={statuses:{title:'Статусы',items:'statuses',permission:'settings.manageStatuses'},leadSources:{title:'Источники лидов',items:'leadSources',permission:'settings.manageLeadSources'},refusalReasons:{title:'Причины отказа',items:'refusalReasons',permission:'settings.manageRefusalReasons'},paymentMethods:{title:'Способы оплаты',items:'paymentMethods',permission:'settings.managePaymentMethods'},tags:{title:'Теги клиентов',items:'tags',permission:'settings.manageTags'}};
function renderSettingsV2(outlet){const d=state.data,cards=Object.entries(configUi).filter(([,cfg])=>can(cfg.permission)).map(([type,cfg])=>`<section class="panel"><div class="panel-head"><h2>${cfg.title}</h2><button class="link" data-config-add="${type}">＋ Добавить</button></div><ul class="config-list">${[...d[cfg.items]].sort((a,b)=>(a.sortOrder||0)-(b.sortOrder||0)).map(item=>`<li><span>${item.color?`<i class="config-color" style="background:${item.color}"></i>`:''}<b>${escapeHtml(displayName(item))}</b>${item.actionType&&item.actionType!=='NONE'?`<div class="subline">${actionTypeLabel(item.actionType)}</div>`:''}</span><span class="config-actions"><small>${item.active?'Активен':'В архиве'}</small><button class="btn btn-ghost" data-config-edit="${type}:${item.id}">Изменить</button><button class="btn ${item.active?'btn-danger':'btn-secondary'}" data-config-toggle="${type}:${item.id}:${item.active?'archive':'restore'}">${item.active?'В архив':'Восстановить'}</button></span></li>`).join('')}</ul></section>`).join('');outlet.innerHTML=`${pageHead('Администрирование','Настройки CRM','Все изменения справочников сохраняются и не удаляют исторические данные.')}<div class="settings-grid">${cards}${can('settings.manageBranding')?`<section class="panel"><div class="panel-head"><h2>Брендинг</h2><span class="subline">Сохраняется после обновления страницы</span></div><form id="branding-form-v2"><div class="branding-row">${d.branding.logoUrl?`<img class="logo-preview" src="${escapeHtml(d.branding.logoUrl)}" alt="Логотип">`:'<span class="brand-mark">M</span>'}<div class="field"><label>Логотип компании</label><input name="logo" type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml"></div></div><div class="field"><label>Название компании</label><input name="companyName" value="${escapeHtml(d.branding.companyName)}" required></div><div class="field"><label>Акцентный цвет</label><input name="accentColor" type="color" value="${d.branding.accentColor}"></div><button class="btn btn-primary">Сохранить брендинг</button></form></section>`:''}</div>`;outlet.querySelectorAll('[data-config-add]').forEach(btn=>btn.onclick=()=>showConfigModal(btn.dataset.configAdd));outlet.querySelectorAll('[data-config-edit]').forEach(btn=>btn.onclick=()=>{const [type,itemId]=btn.dataset.configEdit.split(':');showConfigModal(type,d[configUi[type].items].find(x=>x.id===itemId))});outlet.querySelectorAll('[data-config-toggle]').forEach(btn=>btn.onclick=async()=>{const [type,itemId,action]=btn.dataset.configToggle.split(':');try{await request(`/api/admin/config/${type}/${itemId}/${action}`,{method:'POST'});toast(action==='archive'?'Элемент перенесён в архив':'Элемент восстановлен');await refreshData()}catch(err){toast(err.message,true)}});const form=outlet.querySelector('#branding-form-v2');if(form)form.onsubmit=async e=>{e.preventDefault();try{const fd=new FormData(form),file=fd.get('logo'),logoUrl=file?.size?await fileData(file):d.branding.logoUrl;await request('/api/admin/branding',{method:'PUT',body:JSON.stringify({companyName:fd.get('companyName'),accentColor:fd.get('accentColor'),logoUrl})});toast('Брендинг сохранён');await refreshData()}catch(err){toast(err.message,true)}}}
function showConfigModal(type,item=null){const statusFields=type==='statuses'?`<div class="field"><label>Цвет статуса</label><input name="color" type="color" value="${item?.color||'#4F6BED'}"></div><div class="field"><label>Поведение</label><select name="actionType"><option value="NONE">Обычный результат</option><option value="MARK_NO_SHOW">Неявка</option><option value="REQUIRE_REFUSAL_REASON">Требовать причину отказа</option><option value="REQUIRE_RESCHEDULE">Требовать перенос</option><option value="REQUIRE_PAYMENT">Требовать оплату</option></select></div>`:type==='tags'?`<div class="field"><label>Цвет тега</label><input name="color" type="color" value="${item?.color||'#EDF0F5'}"></div>`:'';showModal(`<h2>${item?'Изменить':'Добавить'}: ${configUi[type].title}</h2><form id="config-form"><div class="field"><label>Название *</label><input name="name" value="${escapeHtml(item?.name||'')}" required></div>${statusFields}<div class="field"><label>Порядок</label><input name="sortOrder" type="number" value="${item?.sortOrder??0}"></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close-modal>Отмена</button><button class="btn btn-primary">Сохранить</button></div></form>`);const form=document.querySelector('#config-form');if(item&&form.actionType)form.actionType.value=item.actionType||'NONE';form.onsubmit=async e=>{e.preventDefault();try{await request(`/api/admin/config/${type}${item?`/${item.id}`:''}`,{method:item?'PUT':'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});closeModal();toast('Настройка сохранена');await refreshData()}catch(err){toast(err.message,true)}}}
function renderProfileV2(outlet){const me=state.data.me;outlet.innerHTML=`${pageHead('Учётная запись','Профиль','Имя, фото и рабочий статус используются во всех общих карточках.')}<form class="panel" id="profile-form" style="max-width:670px"><div class="client-cell profile-avatar-row"><span data-avatar-preview>${avatar(me,roleLabel(me.role))}</span><div><h2>${escapeHtml(me.name)}</h2><div class="subline">${roleLabel(me.role)}</div><div class="subline" data-avatar-state>${me.avatarUrl?'Фото сохранено':'Используются инициалы'}</div></div><label class="btn btn-ghost file-button">Выбрать фото<input name="avatar" type="file" accept="image/png,image/jpeg,image/webp" hidden></label></div><div class="form-grid"><div class="field"><label>Имя</label><input name="name" value="${escapeHtml(me.name)}" required></div><div class="field"><label>Логин</label><input name="login" value="${escapeHtml(me.login)}" required></div><div class="field"><label>Статус профиля</label><select name="profileStatus"><option value="WORKING">Работает</option><option value="DAY_OFF">Выходной</option><option value="NOT_ACCEPTING">Не принимает пробные уроки</option></select></div><div class="field"><label>Новый пароль</label><input name="password" type="password" minlength="6" placeholder="Оставьте пустым без изменений"></div></div><button class="btn btn-primary">Сохранить профиль</button></form>`;const form=outlet.querySelector('#profile-form'),fileInput=form.avatar,preview=form.querySelector('[data-avatar-preview]'),stateLabel=form.querySelector('[data-avatar-state]');let selectedAvatarUrl=null;form.profileStatus.value=me.profileStatus;fileInput.onchange=async()=>{try{const file=fileInput.files?.[0];if(!file)return;selectedAvatarUrl=await cropAvatarFile(file);preview.innerHTML=avatar({...me,avatarUrl:selectedAvatarUrl},roleLabel(me.role));stateLabel.textContent='Предпросмотр — нажмите «Сохранить профиль»';}catch(err){fileInput.value='';selectedAvatarUrl=null;if(err.message!=='Выбор фото отменён')toast(err.message,true)}};form.onsubmit=async e=>{e.preventDefault();try{const fd=new FormData(form),avatarUrl=selectedAvatarUrl??me.avatarUrl,saved=await request('/api/profile',{method:'PUT',body:JSON.stringify({name:fd.get('name'),login:fd.get('login'),profileStatus:fd.get('profileStatus'),password:fd.get('password')||undefined,avatarUrl})});state.data.me=saved;toast('Профиль и фото сохранены');await refreshData()}catch(err){toast(err.message,true)}}}
async function renderAudit(outlet){outlet.innerHTML=`${pageHead('Безопасность','Журнал аудита','Изменения ролей, разрешений, областей данных и брендинга.')}<div class="boot" style="min-height:260px"><span class="spinner"></span></div>`;try{const items=await request('/api/audit');outlet.innerHTML=`${pageHead('Безопасность','Журнал аудита','Изменения ролей, разрешений, областей данных и брендинга.')}<div class="table-wrap"><table><thead><tr><th>Дата</th><th>Пользователь</th><th>Действие</th><th>Объект</th><th>Изменение</th></tr></thead><tbody>${items.map(item=>`<tr><td>${dateTime(item.createdAt)}</td><td>${escapeHtml(item.actor?.name||'Система')}</td><td>${escapeHtml(item.action)}</td><td>${escapeHtml(item.entityType)} · ${escapeHtml(item.entityId)}</td><td><span class="subline">${escapeHtml(JSON.stringify(item.newValue||{})).slice(0,160)}</span></td></tr>`).join('')}</tbody></table></div>`}catch(err){toast(err.message,true)}}
function renderProfile(outlet){const me=state.data.me;outlet.innerHTML=`${pageHead('Учётная запись','Профиль','Управляйте личными данными и статусом доступности.')}<section class="panel" style="max-width:670px"><div class="client-cell" style="margin-bottom:24px">${avatar(me,roleLabel(me.role))}<div><h2 style="margin:0">${escapeHtml(me.name)}</h2><div class="subline">${roleLabel(me.role)}</div></div><button class="btn btn-ghost" style="margin-left:auto">Загрузить фото</button></div><div class="form-grid"><div class="field"><label>Имя</label><input value="${escapeHtml(me.name)}"></div><div class="field"><label>Логин</label><input value="${escapeHtml(me.login)}"></div><div class="field wide"><label>Статус профиля</label><select><option ${me.profileStatus==='WORKING'?'selected':''}>Работает</option><option ${me.profileStatus==='DAY_OFF'?'selected':''}>Выходной</option><option ${me.profileStatus==='NOT_ACCEPTING'?'selected':''}>Не принимает пробные уроки</option></select></div></div><button class="btn btn-primary">Сохранить профиль</button></section>`}

function bindClientClicks(){document.querySelectorAll('[data-client]').forEach(el=>el.onclick=()=>openClient(el.dataset.client));document.querySelectorAll('[data-page-empty]').forEach(el=>el.onclick=()=>{state.page=el.dataset.pageEmpty;renderShell()})}
async function openClient(cid){state.selectedClient=cid;document.querySelector('.scrim')?.remove();document.querySelector('.drawer')?.remove();document.body.insertAdjacentHTML('beforeend','<div class="scrim" data-close-drawer></div><aside class="drawer"><div class="boot" style="min-height:100vh"><span class="spinner"></span></div></aside>');document.querySelector('[data-close-drawer]').onclick=closeDrawer;try{state.drawerData=await request(`/api/clients/${cid}`);renderDrawer()}catch(e){closeDrawer();toast(e.message,true)}}
function closeDrawer(){document.querySelector('.scrim')?.remove();document.querySelector('.drawer')?.remove();state.selectedClient=null}
const eventNames={CLIENT_CREATED:'Клиент создан',TRIAL_SCHEDULED:'Пробный урок запланирован',TRIAL_RESCHEDULED:'Пробный урок перенесён',STATUS_CHANGED:'Статус изменён',NOTE_ADDED:'Заметка добавлена',PAYMENT_CREATED:'Оплата зафиксирована',PAYMENT_CORRECTED:'Оплата скорректирована',MANAGER_CHANGED:'Менеджер переназначен',CLOSER_CHANGED:'Клоузер переназначен',MANAGER_REASSIGNED:'Менеджер переназначен',CLOSER_REASSIGNED:'Клоузер переназначен',CLIENT_ARCHIVED:'Клиент перемещён в архив',CLIENT_RESTORED:'Клиент восстановлен из архива',CLIENT_PERMANENTLY_DELETED:'Клиент удалён без возможности восстановления'};
function renderDrawer(){const d=state.drawerData,c=d.client,canChange=canAny('clients.changeStatus','crm.changeStatus');document.querySelector('.drawer').innerHTML=`<header class="drawer-head"><button class="drawer-close" data-close-drawer>×</button><div class="eyebrow">Общая карточка клиента</div><h1>${escapeHtml(c.name)}</h1><div>${statusPill(c.status)} ${c.overdue?'<span class="overdue-label">! Результат просрочен</span>':''}</div><div class="drawer-owners">${avatars(c)}<div class="owner-names"><b>Менеджер:</b> ${escapeHtml(c.manager.name)} · <b>Клоузер:</b> ${escapeHtml(c.closer.name)}</div></div></header><div class="drawer-body"><section class="drawer-section"><div class="drawer-actions">${canChange?'<button class="btn btn-primary" data-status>Изменить статус</button>':''}${can('clients.addNotes')?'<button class="btn btn-secondary" data-note>Добавить заметку</button>':''}${canAny('clients.reassignManager','clients.reassignCloser')?'<button class="btn btn-ghost">Переназначить</button>':''}</div></section><section class="drawer-section"><h2>Данные клиента</h2><div class="info-grid"><div class="info"><small>Телефон</small><b>${escapeHtml(c.normalizedPhone)}</b></div><div class="info"><small>Источник лида</small><b>${escapeHtml(displayName(c.leadSource))}</b></div><div class="info"><small>Активный пробный урок</small><b>${c.activeTrial?dateTime(c.activeTrial.scheduledAt):'Нет активного урока'}</b></div><div class="info"><small>Теги</small>${tagPills(c.tags)}</div></div></section><section class="drawer-section"><h2>Комментарий менеджера при регистрации</h2><div class="comment">${escapeHtml(c.registrationComment||'Комментарий не добавлен.')}</div></section>${can('payments.viewHistory')&&d.payments.length?`<section class="drawer-section"><h2>История оплат</h2>${d.payments.map(p=>`<div class="payment-card"><div><strong>${money(p.amount)}</strong><small>${escapeHtml(p.method?displayName(p.method):'Архивный способ')} · ${p.paymentDate}</small></div><div class="subline">Клоузер<br><b>${escapeHtml(p.closer.name)}</b></div></div>`).join('')}</section>`:''}${can('clients.viewHistory')?`<section class="drawer-section"><h2>Заметки</h2>${d.notes.length?d.notes.map(n=>`<article class="note"><div class="note-head"><b>${escapeHtml(n.author.name)} · ${roleLabel(n.author.role)}</b><span>${dateTime(n.createdAt)}</span></div><p>${escapeHtml(n.text)}</p></article>`).join(''):'<p class="subline">Заметок пока нет.</p>'}</section><section class="drawer-section"><h2>История действий</h2><div class="timeline">${d.history.map(h=>`<div class="timeline-item"><b>${eventNames[h.eventType]||h.eventType}</b><span>${escapeHtml(h.actor.name)} · ${dateTime(h.createdAt)}</span></div>`).join('')}</div></section>`:''}</div>`;document.querySelectorAll('[data-close-drawer]').forEach((el)=>el.onclick=closeDrawer);document.querySelector('[data-note]')?.addEventListener('click',showNoteModal);document.querySelector('[data-status]')?.addEventListener('click',showStatusModalV2)}
function showNoteModal(){showModal(`<h2>Добавить заметку</h2><p>Вместе с заметкой сохранятся ваше имя, роль, дата и время. Старые заметки не перезаписываются.</p><form id="note-form"><div class="field"><label>Заметка</label><textarea name="text" required autofocus placeholder="Добавьте полезный контекст для команды…"></textarea></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close-modal>Отмена</button><button class="btn btn-primary">Добавить заметку</button></div></form>`);document.querySelector('#note-form').onsubmit=async e=>{e.preventDefault();try{await request(`/api/clients/${state.selectedClient}/notes`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeModal();toast('Заметка добавлена');state.drawerData=await request(`/api/clients/${state.selectedClient}`);renderDrawer()}catch(err){toast(err.message,true)}}}
function showStatusModal(){const statuses=state.data.statuses.filter(s=>s.active).sort((a,b)=>a.sortOrder-b.sortOrder);showModal(`<h2>Изменить статус клиента</h2><p>Обязательные поля определяются настройками выбранного статуса.</p><form id="status-form"><div class="field"><label>Новый статус</label><select name="statusId" id="status-select">${statuses.map(s=>`<option value="${s.id}" ${s.id===state.drawerData.client.currentStatusId?'selected':''}>${escapeHtml(displayName(s))}</option>`).join('')}</select></div><div id="status-extra"></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close-modal>Отмена</button><button class="btn btn-primary">Сохранить статус</button></div></form>`);const renderExtra=async()=>{const s=statuses.find(x=>x.id===document.querySelector('#status-select').value),box=document.querySelector('#status-extra');if(s.actionType==='REQUIRE_REFUSAL_REASON')box.innerHTML=`<div class="field"><label>Причина отказа *</label><select name="refusalReasonId" required><option value="">Выберите причину</option>${state.data.refusalReasons.filter(x=>x.active).map(x=>`<option value="${x.id}">${escapeHtml(displayName(x))}</option>`).join('')}</select></div>`;else if(s.actionType==='REQUIRE_PAYMENT')box.innerHTML=`<div class="form-grid"><div class="field"><label>Сумма *</label><input type="number" name="amount" min="1" required></div><div class="field"><label>Дата оплаты *</label><input type="date" name="paymentDate" value="${today()}" required></div><div class="field wide"><label>Способ оплаты *</label><select name="paymentMethodId" required>${state.data.paymentMethods.filter(x=>x.active).map(x=>`<option value="${x.id}">${escapeHtml(displayName(x))}</option>`).join('')}</select></div><div class="field wide"><label>Комментарий</label><input name="paymentComment"></div></div>`;else if(s.actionType==='REQUIRE_RESCHEDULE'){await loadSlots(state.drawerData.client.currentCloserId,state.slotDate);box.innerHTML=`<div class="field"><label>Новая дата *</label><input type="date" id="reschedule-date" min="${today()}" value="${state.slotDate}"></div><div class="field"><label>Свободное время *</label><select name="newSlotId" id="new-slot" required><option value="">Выберите свободное время</option>${state.slots.filter(x=>x.status==='FREE').map(x=>`<option value="${x.id}">${time(x.startAt)}</option>`).join('')}</select></div>`;document.querySelector('#reschedule-date').onchange=async e=>{state.slotDate=e.target.value;await renderExtra()}}else box.innerHTML=''};document.querySelector('#status-select').onchange=renderExtra;renderExtra();document.querySelector('#status-form').onsubmit=async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(e.currentTarget));try{await request(`/api/clients/${state.selectedClient}/status`,{method:'POST',body:JSON.stringify(payload)});closeModal();toast('Статус обновлён');await refreshData();state.drawerData=await request(`/api/clients/${state.selectedClient}`);renderDrawer()}catch(err){toast(err.message,true)}}}
function showStatusModalV2(){const statuses=state.data.statuses.filter(s=>s.active).sort((a,b)=>a.sortOrder-b.sortOrder),manager=state.data.me.role==='MANAGER',allowed=s=>!manager||['REQUIRE_RESCHEDULE','MARK_NO_SHOW'].includes(s.actionType),current=state.drawerData.client.status;showModal(`<h2>Изменить статус клиента</h2><p>Текущий статус: <b>${escapeHtml(displayName(current))}</b>. Обязательные поля определяются настройками статуса.</p>${manager?'<div class="permission-warning">Менеджер может отметить неявку или перенести урок. Остальные результаты фиксирует клоузер.</div>':''}<form id="status-form-v2"><div class="field"><label>Новый статус</label><select name="statusId" id="status-select-v2" required><option value="">Выберите статус</option>${statuses.map(s=>`<option value="${s.id}" ${!allowed(s)?'disabled':''}>${escapeHtml(displayName(s))}${!allowed(s)?' · только клоузер':''}</option>`).join('')}</select></div><div id="status-extra-v2"></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close-modal>Отмена</button><button class="btn btn-primary">Сохранить статус</button></div></form>`);const form=document.querySelector('#status-form-v2'),select=document.querySelector('#status-select-v2'),box=document.querySelector('#status-extra-v2');const renderExtra=async()=>{const s=statuses.find(x=>x.id===select.value);box.innerHTML='';if(!s)return;if(!allowed(s)){box.innerHTML='<div class="permission-warning">Этот статус может изменить только клоузер</div>';return}if(s.actionType==='REQUIRE_REFUSAL_REASON')box.innerHTML=`<div class="field"><label>Причина отказа *</label><select name="refusalReasonId" required><option value="">Выберите причину</option>${state.data.refusalReasons.filter(x=>x.active).map(x=>`<option value="${x.id}">${escapeHtml(displayName(x))}</option>`).join('')}</select></div>`;else if(s.actionType==='REQUIRE_PAYMENT')box.innerHTML=`<div class="form-grid"><div class="field"><label>Сумма *</label><input type="number" name="amount" min="1" required></div><div class="field"><label>Дата оплаты *</label><input type="date" name="paymentDate" value="${today()}" required></div><div class="field wide"><label>Способ оплаты *</label><select name="paymentMethodId" required>${state.data.paymentMethods.filter(x=>x.active).map(x=>`<option value="${x.id}">${escapeHtml(displayName(x))}</option>`).join('')}</select></div><div class="field wide"><label>Комментарий</label><input name="paymentComment"></div></div>`;else if(s.actionType==='REQUIRE_RESCHEDULE'){await loadSlots(state.drawerData.client.currentCloserId,state.slotDate);box.innerHTML=`<div class="field"><label>Новая дата *</label><input type="date" id="reschedule-date-v2" min="${today()}" value="${state.slotDate}" required></div><div class="field"><label>Свободное время *</label><select name="newSlotId" required><option value="">Выберите свободное время</option>${state.slots.filter(x=>x.status==='FREE').map(x=>`<option value="${x.id}">${time(x.startAt)}</option>`).join('')}</select></div>`;document.querySelector('#reschedule-date-v2').onchange=async e=>{state.slotDate=e.target.value;await renderExtra()}}};select.onchange=renderExtra;form.onsubmit=async e=>{e.preventDefault();const selected=statuses.find(s=>s.id===select.value);if(!selected)return toast('Выберите новый статус',true);if(!allowed(selected))return toast('Этот статус может изменить только клоузер',true);try{await request(`/api/clients/${state.selectedClient}/status`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});closeModal();toast('Статус обновлён');await refreshData();state.drawerData=await request(`/api/clients/${state.selectedClient}`);renderDrawer()}catch(err){toast(err.message,true)}}}
function showModal(html){document.body.insertAdjacentHTML('beforeend',`<div class="scrim modal-scrim" data-close-modal></div><section class="modal">${html}</section>`);document.querySelectorAll('[data-close-modal]').forEach(el=>el.onclick=closeModal)}
function closeModal(){document.querySelector('.modal-scrim')?.remove();document.querySelector('.modal')?.remove()}
async function refreshData(){state.data=await request('/api/bootstrap');renderShell()}

function enhanceClientDrawer(){
  const body=document.querySelector('.drawer-body');if(!body||body.dataset.enhanced||!state.drawerData)return;
  body.dataset.enhanced='true';const d=state.drawerData,c=d.client,archived=Boolean(c.archivedAt),actions=body.querySelector('.drawer-actions'),comment=[...body.querySelectorAll('.drawer-section')].find(section=>section.querySelector('h2')?.textContent.includes('Комментарий'));
  if(archived){
    actions?.querySelectorAll('button').forEach(button=>button.remove());
    document.querySelector('.drawer-head h1')?.insertAdjacentHTML('afterend',`<div class="archive-drawer-state"><span class="archive-badge">В архиве</span><small>Причина: ${escapeHtml(c.archiveReasonLabel||'—')} · ${escapeHtml(c.archivedBy?.name||'Система')} · ${dateTime(c.archivedAt)}</small></div>`);
  }
  if(actions&&can('clients.archive')){const button=document.createElement('button');button.className=archived?'btn btn-secondary':'btn btn-ghost';button.textContent=archived?'Восстановить':'Архив';button.onclick=()=>archived?restoreArchivedClient(c.id):showArchiveClientModal(c);actions.append(button)}
  if(actions&&state.data.me.isOwner){const button=document.createElement('button');button.className='btn btn-danger';button.textContent='Удалить';button.onclick=()=>showPermanentDeleteModal(c);actions.append(button)}
  if(can('clients.viewHistory')&&d.trials.length)comment?.insertAdjacentHTML('afterend',`<section class="drawer-section"><h2>Оплата пробного</h2>${d.trials.map(t=>`<div class="trial-payment-card"><div><b>${t.trialType==='PAID'?'Платный':'Бесплатный'}</b><span>${t.trialType==='PAID'?money(t.trialAmount):money(0)}</span></div><small>${t.trialPaymentDate||dayFromIso(t.createdAt)} · ${escapeHtml(t.registeredBy?.name||'Менеджер')}</small>${t.receiptUrl?`<a class="btn btn-ghost" href="${escapeHtml(t.receiptUrl)}" target="_blank" rel="noopener">Открыть чек</a>`:''}</div>`).join('')}</section>`);
  if(can('clients.viewHistory')&&d.trials.length)comment?.insertAdjacentHTML('afterend',`<section class="drawer-section"><h2>История пробных уроков</h2><div class="trial-history">${d.trials.map(t=>`<div class="info"><small>${t.active?'Активный':'Исторический'} · ${t.completedAt?'проведён':'без результата'}</small><b>${dateTime(t.scheduledAt)}</b><div class="subline">${t.closerId===c.currentCloserId?escapeHtml(c.closer?.name||'Клоузер'):'Историческая атрибуция сохранена'}</div></div>`).join('')}</div></section>`);
  const reassign=[...document.querySelectorAll('.drawer-actions button')].find(btn=>btn.textContent.includes('Переназначить'));if(reassign)reassign.onclick=showReassignModal;
  body.querySelectorAll('.payment-card').forEach((card,index)=>{const payment=d.payments[index];if(!payment)return;if(payment.voidedAt){card.classList.add('payment-voided');card.insertAdjacentHTML('beforeend','<span class="subline">Исправлена</span>')}else if(!archived&&can('payments.edit')){const button=document.createElement('button');button.className='btn btn-ghost';button.textContent='Исправить';button.onclick=()=>showPaymentCorrection(payment);card.append(button)}});
  body.querySelectorAll('.timeline-item').forEach((item,index)=>{const entry=d.history[index];if(entry?.eventType==='CLIENT_ARCHIVED'&&entry.newValue?.reasonLabel)item.insertAdjacentHTML('beforeend',`<small class="timeline-detail">Причина: ${escapeHtml(entry.newValue.reasonLabel)}</small>`)});
}

function showArchiveClientModal(c){const reasons=state.data.archiveReasons||{DUPLICATE:'Дубль',TEST:'Тест',ERROR:'Ошибка'};showModal(`<h2>Причина архивации</h2><p>Клиент исчезнет из активных списков, но карточка, пробные уроки, оплаты и история сохранятся.</p><form id="archive-client-form"><div class="archive-reasons">${Object.entries(reasons).map(([value,label])=>`<label><input type="radio" name="reason" value="${value}" required><span>${escapeHtml(label)}</span></label>`).join('')}</div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close-modal>Отмена</button><button class="btn btn-primary">Переместить в архив</button></div></form>`);document.querySelector('#archive-client-form').onsubmit=async event=>{event.preventDefault();const reason=new FormData(event.currentTarget).get('reason');if(!reason)return toast('Выберите причину архивации',true);try{await request(`/api/clients/${c.id}/archive`,{method:'POST',body:JSON.stringify({reason})});closeModal();closeDrawer();toast('Клиент перемещён в архив');await refreshData()}catch(err){toast(err.message,true)}}}
async function restoreArchivedClient(clientId){try{await request(`/api/clients/${clientId}/restore`,{method:'POST'});closeDrawer();toast('Клиент восстановлен из архива');await refreshData()}catch(err){toast(err.message,true)}}
function showPermanentDeleteModal(c){showModal(`<div class="destructive-heading"><span>!</span><div><h2>Удалить клиента без возможности восстановления?</h2><p>Клиент, оплаты, пробные уроки, заметки, история и уведомления будут полностью удалены.</p></div></div><div class="danger-notice">Это действие нельзя отменить. В аудите останется только факт удаления и ID клиента.</div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close-modal>Отмена</button><button type="button" class="btn btn-danger" data-delete-next>Продолжить</button></div>`);document.querySelector('[data-delete-next]').onclick=()=>{closeModal();showPermanentDeleteConfirm(c)}}
function showPermanentDeleteConfirm(c){showModal(`<h2>Подтвердите постоянное удаление</h2><p>Клиент «${escapeHtml(c.name)}» и вся связанная с ним финансовая и учебная история будут полностью удалены.</p><div class="danger-notice">Нажимая «Удалить навсегда», вы подтверждаете окончательное удаление клиента.</div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close-modal>Отмена</button><button type="button" class="btn btn-danger" data-delete-final>Удалить навсегда</button></div>`);document.querySelector('[data-delete-final]').onclick=async event=>{const button=event.currentTarget;button.disabled=true;button.textContent='Удаляем…';try{await request(`/api/clients/${c.id}`,{method:'DELETE',body:JSON.stringify({confirmation:'УДАЛИТЬ'})});closeModal();closeDrawer();toast('Клиент и вся связанная история удалены');await refreshData()}catch(err){button.disabled=false;button.textContent='Удалить навсегда';toast(err.message,true)}}}
function showPaymentCorrection(payment){showModal(`<h2>Корректировка оплаты</h2><p>Исходная запись останется в истории и будет помечена исправленной.</p><form id="payment-correction"><div class="form-grid"><div class="field"><label>Сумма *</label><input name="amount" type="number" min="1" value="${payment.amount}" required></div><div class="field"><label>Дата оплаты *</label><input name="paymentDate" type="date" value="${payment.paymentDate}" required></div><div class="field wide"><label>Способ оплаты *</label><select name="paymentMethodId">${state.data.paymentMethods.filter(m=>m.active).map(m=>`<option value="${m.id}" ${m.id===payment.paymentMethodId?'selected':''}>${escapeHtml(displayName(m))}</option>`).join('')}</select></div><div class="field wide"><label>Комментарий</label><input name="comment" value="${escapeHtml(payment.comment||'')}"></div></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close-modal>Отмена</button><button class="btn btn-primary">Сохранить исправление</button></div></form>`);document.querySelector('#payment-correction').onsubmit=async e=>{e.preventDefault();try{await request(`/api/payments/${payment.id}/correct`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeModal();toast('Оплата скорректирована');state.drawerData=await request(`/api/clients/${state.selectedClient}`);renderDrawer()}catch(err){toast(err.message,true)}}}
function showReassignModal(){const c=state.drawerData.client,managers=state.data.users.filter(u=>u.role==='MANAGER'&&u.active),closers=state.data.users.filter(u=>u.role==='CLOSER'&&u.active);showModal(`<h2>Переназначить клиента</h2><p>Историческая атрибуция старых уроков и оплат не изменится.</p><form id="reassign-form">${can('clients.reassignManager')?`<div class="field"><label>Менеджер</label><select name="managerId">${managers.map(u=>`<option value="${u.id}" ${u.id===c.currentManagerId?'selected':''}>${escapeHtml(u.name)}</option>`).join('')}</select></div>`:''}${can('clients.reassignCloser')?`<div class="field"><label>Клоузер</label><select name="closerId" id="reassign-closer">${closers.map(u=>`<option value="${u.id}" ${u.id===c.currentCloserId?'selected':''}>${escapeHtml(u.name)}</option>`).join('')}</select></div>${c.activeTrial?`<div class="field"><label>Дата нового урока</label><input type="date" id="reassign-date" min="${today()}" value="${state.slotDate}"></div><div class="field"><label>Свободное время нового клоузера</label><select name="newSlotId" id="reassign-slot"><option value="">Не требуется без смены клоузера</option></select></div>`:''}`:''}<div class="modal-actions"><button type="button" class="btn btn-ghost" data-close-modal>Отмена</button><button class="btn btn-primary">Сохранить назначение</button></div></form>`);const form=document.querySelector('#reassign-form'),refresh=async()=>{if(!c.activeTrial||!form.closerId)return;await loadSlots(form.closerId.value,document.querySelector('#reassign-date').value);document.querySelector('#reassign-slot').innerHTML=`<option value="">${form.closerId.value===c.currentCloserId?'Не требуется без смены клоузера':'Выберите свободное время'}</option>${state.slots.filter(s=>s.status==='FREE').map(s=>`<option value="${s.id}">${time(s.startAt)}</option>`).join('')}`};form.closerId?.addEventListener('change',refresh);document.querySelector('#reassign-date')?.addEventListener('change',refresh);refresh();form.onsubmit=async e=>{e.preventDefault();try{await request(`/api/clients/${state.selectedClient}/reassign`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});closeModal();toast('Назначение сохранено');await refreshData();openClient(c.id)}catch(err){toast(err.message,true)}}}
const drawerObserver=new MutationObserver(()=>enhanceClientDrawer());drawerObserver.observe(document.body,{childList:true,subtree:true});

window.addEventListener('beforeunload',e=>{const focused=document.activeElement;if(focused&&['TEXTAREA','INPUT'].includes(focused.tagName)&&focused.value&&focused.form){e.preventDefault();e.returnValue=''}});
boot();
